{"security_risk": "LOW", "summary": "List all paths in OpenAPI contract", "command": "python3 -c "
import json
with open('/workspace/contracts/openapi.contract.json') as f:
    contract = json.load(f)
print('Number of paths:', len(contract['paths']))
print('Paths:')
for path in contract['paths']:
    methods = list(contract['paths'][path].keys())
    for m in methods:
        if m in ['get','post','put','delete','patch']:
            op = contract['paths'][path][m]
            print(f'  {m.upper():6} {path:60} -> {op.get(\"operationId\",\"NO_OP_ID\")}')""}

