package store

import (
	"context"
	"embed"
	"fmt"
	"sort"
	"strings"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

//go:embed migrations/*.sql
var migrations embed.FS

type Postgres struct {
	pool *pgxpool.Pool
}

func NewPostgres(ctx context.Context, url string) (*Postgres, error) {
	cfg, err := pgxpool.ParseConfig(url)
	if err != nil {
		return nil, err
	}
	cfg.MaxConns = 16
	pool, err := pgxpool.NewWithConfig(ctx, cfg)
	if err != nil {
		return nil, err
	}
	p := &Postgres{pool: pool}
	if err := p.Ping(ctx); err != nil {
		return nil, err
	}
	return p, nil
}

func (p *Postgres) Pool() *pgxpool.Pool { return p.pool }

func (p *Postgres) Ping(ctx context.Context) error {
	c, cancel := context.WithTimeout(ctx, 3*time.Second)
	defer cancel()
	return p.pool.Ping(c)
}

func (p *Postgres) Close() { p.pool.Close() }

// Reset drops and recreates all schema and indexes in a single transaction.
func (p *Postgres) Reset(ctx context.Context) error {
	conn, err := p.pool.Acquire(ctx)
	if err != nil {
		return err
	}
	defer conn.Release()
	drop := `
		DROP TABLE IF EXISTS audit CASCADE;
		DROP TABLE IF EXISTS timeline CASCADE;
		DROP TABLE IF EXISTS handoff CASCADE;
		DROP TABLE IF EXISTS assignment CASCADE;
		DROP TABLE IF EXISTS journey_stop CASCADE;
		DROP TABLE IF EXISTS journey CASCADE;
		DROP TABLE IF EXISTS sample CASCADE;
		DROP TABLE IF EXISTS request CASCADE;
		DROP TABLE IF EXISTS sample_type CASCADE;
		DROP TABLE IF EXISTS connection CASCADE;
		DROP TABLE IF EXISTS location CASCADE;
		DROP TABLE IF EXISTS user_session CASCADE;
		DROP TABLE IF EXISTS app_user CASCADE;
		DROP TABLE IF EXISTS serviceability_snapshot CASCADE;
		DROP TABLE IF EXISTS app_meta CASCADE;
	`
