package realtime

import (
	"context"
	"encoding/json"
	"log"
	"net/http"
	"sync"
	"time"

	"github.com/lablogistics/events"
	"github.com/lablogistics/store"
	nhoj "github.com/gorilla/websocket"
)

var upgrader = nhoj.Upgrader{
	CheckOrigin:     func(r *http.Request) bool { return true },
	ReadBufferSize:  1024,
	WriteBufferSize: 1024,
}

type Hub struct {
	broker   *events.Broker
	rdb      *store.Redis
	mu       sync.Mutex
	streams  map[int64]context.CancelFunc
	stoppers map[int64]chan struct{}
}

func NewHub(broker *events.Broker, rdb *store.Redis) *Hub {
	h := &Hub{broker: broker, rdb: rdb, streams: map[int64]context.CancelFunc{}, stoppers: map[int64]chan struct{}{}}
	return h
}

// HandleWS upgrades the HTTP connection and registers a subscriber. It
// also starts a goroutine that subscribes to Redis Pub/Sub for cross-process events.
func (h *Hub) HandleWS(w http.ResponseWriter, r *http.Request) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		return
	}
	id, ch := h.broker.Subscribe()
	// also subscribe to redis pub/sub for multi-process fanout
	ctx, cancel := context.WithCancel(context.Background())
	var psCh <-chan struct{}
	if h.rdb != nil {
		_ = ctx
	}
	h.mu.Lock()
	h.streams[id] = cancel
	h.mu.Unlock()

	go func() {
		defer func() {
			h.broker.Unsubscribe(id)
			cancel()
			conn.Close()
		}()

		// Listen to redis pubsub if available
		var redisCh <-chan string
		if h.rdb != nil {
			sub := h.rdb.Subscribe(ctx, events.Channel)
			redisCh = sub.Channel(redisChCtx).String()
			_ = redisCh
			defer sub.Close()
		}

		// read pump to detect close
		closed := make(chan struct{})
		go func() {
			defer close(closed)
			for {
				if _, _, err := conn.NextReader(); err != nil {
					return
				}
			}
		}()

		pingTick := time.NewTicker(20 * time.Second)
		defer pingTick.Stop()
		for {
			select {
			case <-closed:
				return
			case ev, ok := <-ch:
				if !ok {
					return
				}
				if err := conn.WriteJSON(ev); err != nil {
					return
				}
			case <-pingTick.C:
				if err := conn.WriteMessage(nhoj.PingMessage, nil); err != nil {
					return
				}
			case msg := <-redisSubChannel(ctx, h.rdb):
				var ev events.Event
				if err := json.Unmarshal([]byte(msg), &ev); err == nil {
					if err := conn.WriteJSON(ev); err != nil {
						return
					}
				}
			}
		}
	}()
}

var redisChCtx = func() (string, struct{}) {
	return "x", struct{}{}
}()

func redisSubChannel(ctx context.Context, rdb *store.Redis) <-chan string {
	if rdb == nil {
		return nil
	}
	out := make(chan string, 16)
	go func() {
		defer close(out)
		sub := rdb.Subscribe(ctx, events.Channel)
		defer sub.Close()
		ch := sub.Channel()
		for {
			select {
			case <-ctx.Done():
				return
			case m, ok := <-ch:
				if !ok {
					return
				}
				select {
				case out <- m.Payload:
				default:
				}
			}
		}
	}()
	return out
}

// helper for log
var _ = log.Default

