package service

import (
	"context"
	"encoding/json"
	"fmt"
	"math"
	"time"

	"github.com/lablogistics/models"
	"github.com/lablogistics/store"
)

type Serviceability struct {
	pg *store.Postgres
}

func NewServiceability(pg *store.Postgres) *Serviceability { return &Serviceability{pg: pg} }

// Compute returns the next snapshot version and regions, computing against the
// current network. The previous complete snapshot is returned while a new
// computation is in progress, ensuring no partial snapshot is served.
func (s *Serviceability) Compute(ctx context.Context) (models.ServiceabilitySnapshot, error) {
	// Atomically bump the version by inserting a new row marked computing=true.
	tx, err := s.pg.Begin(ctx)
	if err != nil {
		return s.LastPublished(ctx)
	}
	defer tx.Rollback(ctx)

	var maxV int
	if err := tx.QueryRow(ctx, "SELECT COALESCE(MAX(version),0) FROM serviceability_snapshot").Scan(&maxV); err != nil {
		return s.LastPublished(ctx)
	}
	newV := maxV + 1

	// Build regions from active collection points
