package httpapi

import (
	"encoding/json"
	"net/http"
	"time"

	"github.com/lablogistics/auth"
	"github.com/lablogistics/models"
)

type loginReq struct {
	Username string `json:"username"`
	Password string `json:"password"`
}

type loginResp struct {
	Data struct {
		SessionToken string       `json:"sessionToken"`
		UserID       string       `json:"userId"`
		Roles        []string     `json:"roles"`
		ActiveRole   string       `json:"activeRole"`
	} `json:"data"`
}

func (s *Server) handleAuthenticate(w http.ResponseWriter, r *http.Request) {
	var req loginReq
	if err := readJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if req.Username == "" || req.Password == "" {
		writeError(w, http.StatusBadRequest, "invalid_json", "username and password are required")
		return
	}
	var u models.User
	var rolesRaw string
	var assignedNode, assignedLab string
	var certsRaw string
	row := s.PG.QueryRow(r.Context(), `SELECT id, username, password_hash, full_name, array_to_string(roles, ','), active_role, assigned_node, assigned_lab, array_to_string(certifications, ','), available, created_at FROM app_user WHERE username=$1`, req.Username)
	if err := row.Scan(&u.ID, &u.Username, &u.PasswordHash, &u.FullName, &rolesRaw, &u.ActiveRole, &assignedNode, &assignedLab, &certsRaw, &u.Available, &u.CreatedAt); err != nil {
		writeError(w, http.StatusUnauthorized, "invalid_credentials", "username or password is incorrect")
		return
	}
	if !auth.VerifyPassword(u.PasswordHash, req.Password) {
		writeError(w, http.StatusUnauthorized, "invalid_credentials", "username or password is incorrect")
		return
	}
	if rolesRaw != "" {
		for _, p := range splitComma(rolesRaw) {
			u.Roles = append(u.Roles, models.Role(p))
		}
	}
	if u.ActiveRole == "" && len(u.Roles) > 0 {
		u.ActiveRole = u.Roles[0]
		_, _ = s.PG.Exec(r.Context(), "UPDATE app_user SET active_role=$1 WHERE id=$2", u.ActiveRole, u.ID)
	}
	if certsRaw != "" {
		u.Certs = splitComma(certsRaw)
	}
	u.AssignedNode = assignedNode
	u.AssignedLab = assignedLab

	tok, err := newSession(r.Context(), s.PG, u.ID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	resp := loginResp{}
	resp.Data.SessionToken = tok
	resp.Data.UserID = u.ID
	rolesOut := make([]string, 0, len(u.Roles))
	for _, rl := range u.Roles {
		rolesOut = append(rolesOut, string(rl))
	}
	resp.Data.Roles = rolesOut
	resp.Data.ActiveRole = string(u.ActiveRole)
	s.Audit.Record(r.Context(), u.ID, string(u.ActiveRole), "authenticate", "user", u.ID, true, map[string]any{"ip": r.RemoteAddr})
	writeJSON(w, http.StatusOK, resp)
}

type selectActiveRoleReq struct {
	Role string `json:"role"`
}

type selectActiveRoleResp struct {
	Data struct {
		UserID     string   `json:"userId"`
		Roles      []string `json:"roles"`
		ActiveRole string   `json:"activeRole"`
	} `json:"data"`
}

func (s *Server) handleSelectActiveRole(w http.ResponseWriter, r *http.Request) {
	uid := r.Context().Value(ctxUserID).(string)
	var req selectActiveRoleReq
	if err := readJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	var roles []string
	if err := s.PG.QueryRow(r.Context(), "SELECT roles FROM app_user WHERE id=$1", uid).Scan(&pqStrArr(&roles)); err != nil {
		writeError(w, http.StatusNotFound, "user_not_found", "user not found")
		return
	}
	if req.Role == "" {
		writeError(w, http.StatusBadRequest, "invalid_role", "role required")
		return
	}
	has := false
	for _, rl := range roles {
		if rl == req.Role {
			has = true
			break
		}
	}
	if !has {
		writeError(w, http.StatusConflict, "role_not_assigned", "user does not hold that role")
		return
	}
	if _, err := s.PG.Exec(r.Context(), "UPDATE app_user SET active_role=$1 WHERE id=$2", req.Role, uid); err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	s.Audit.Record(r.Context(), uid, req.Role, "select_active_role", "user", uid, true, map[string]any{"role": req.Role})
	resp := selectActiveRoleResp{}
	resp.Data.UserID = uid
	resp.Data.Roles = roles
	resp.Data.ActiveRole = req.Role
	writeJSON(w, http.StatusOK, resp)
}

type createUserReq struct {
	Username           string   `json:"username"`
	Password           string   `json:"password"`
	FullName           string   `json:"fullName"`
	Roles              []string `json:"roles"`
	AssignedNodeID     string   `json:"assignedNodeId,omitempty"`
	AssignedLabID      string   `json:"assignedLaboratoryId,omitempty"`
	Certifications     []string `json:"certifications"`
}

type userEnvelope struct {
	Data userData `json:"data"`
}

type userData struct {
	UserID             string   `json:"userId"`
	Username           string   `json:"username"`
	FullName           string   `json:"fullName"`
	Roles              []string `json:"roles"`
	ActiveRole         string   `json:"activeRole"`
	AssignedNodeID     string   `json:"assignedNodeId"`
	AssignedLabID      string   `json:"assignedLaboratoryId"`
	Certifications     []string `json:"certifications"`
	Available          bool     `json:"available"`
}

func (s *Server) handleCreateUser(w http.ResponseWriter, r *http.Request) {
	var req createUserReq
	if err := readJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if req.Username == "" || req.Password == "" || req.FullName == "" {
		writeError(w, http.StatusBadRequest, "invalid_json", "username, password, fullName required")
		return
	}
	if len(req.Roles) == 0 {
		writeError(w, http.StatusBadRequest, "invalid_json", "at least one role required")
		return
	}
	hash, err := auth.HashPassword(req.Password)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	id := "usr_" + randID()
	active := req.Roles[0]
	rolesPG := pgTextArr(req.Roles)
	certsPG := pgTextArr(req.Certifications)
	_, err = s.PG.Exec(r.Context(), `INSERT INTO app_user (id, username, password_hash, full_name, roles, active_role, assigned_node, assigned_lab, certifications) VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)`,
		id, req.Username, hash, req.FullName, rolesPG, active, req.AssignedNodeID, req.AssignedLabID, certsPG)
	if err != nil {
		if isUniqueViolation(err) {
			writeError(w, http.StatusConflict, "user_exists", "username already exists")
			return
		}
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	uid := r.Context().Value(ctxUserID).(string)
	role := r.Context().Value(ctxUserRole).(string)
	s.Audit.Record(r.Context(), uid, string(role), "create_user", "user", id, true, map[string]any{"username": req.Username, "roles": req.Roles})

	out := userEnvelope{}
	out.Data.UserID = id
	out.Data.Username = req.Username
	out.Data.FullName = req.FullName
	out.Data.Roles = req.Roles
	out.Data.ActiveRole = active
	out.Data.AssignedNodeID = req.AssignedNodeID
	out.Data.AssignedLabID = req.AssignedLabID
	out.Data.Certifications = req.Certifications
	out.Data.Available = true
	writeJSON(w, http.StatusCreated, out)
}

type updateUserAccessReq struct {
	UserID             string   `json:"userId"`
	Roles              []string `json:"roles"`
	AssignedNodeID     string   `json:"assignedNodeId,omitempty"`
	AssignedLabID      string   `json:"assignedLaboratoryId,omitempty"`
	Certifications     []string `json:"certifications"`
	Available          *bool    `json:"available,omitempty"`
	Password           string   `json:"password,omitempty"`
}

func (s *Server) handleUpdateUserAccess(w http.ResponseWriter, r *http.Request) {
	var req updateUserAccessReq
	if err := readJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if req.UserID == "" {
		writeError(w, http.StatusBadRequest, "invalid_json", "userId required")
		return
	}
	var existing models.User
	var rolesRaw, certsRaw string
	if err := s.PG.QueryRow(r.Context(), `SELECT id, username, full_name, array_to_string(roles, ','), active_role, assigned_node, assigned_lab, array_to_string(certifications, ','), available FROM app_user WHERE id=$1`, req.UserID).Scan(&existing.ID, &existing.Username, &existing.FullName, &rolesRaw, &existing.ActiveRole, &existing.AssignedNode, &existing.AssignedLab, &certsRaw, &existing.Available); err != nil {
		writeError(w, http.StatusNotFound, "user_not_found", "user not found")
		return
	}
	if len(req.Roles) > 0 {
		if _, err := s.PG.Exec(r.Context(), `UPDATE app_user SET roles=$1 WHERE id=$2`, pgTextArr(req.Roles), req.UserID); err != nil {
			writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}
	}
	if req.AssignedNodeID != "" {
		if _, err := s.PG.Exec(r.Context(), `UPDATE app_user SET assigned_node=$1 WHERE id=$2`, req.AssignedNodeID, req.UserID); err != nil {
			writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}
	}
	if req.AssignedLabID != "" {
		if _, err := s.PG.Exec(r.Context(), `UPDATE app_user SET assigned_lab=$1 WHERE id=$2`, req.AssignedLabID, req.UserID); err != nil {
			writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}
	}
	if len(req.Certifications) > 0 {
		if _, err := s.PG.Exec(r.Context(), `UPDATE app_user SET certifications=$1 WHERE id=$2`, pgTextArr(req.Certifications), req.UserID); err != nil {
			writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}
	}
	if req.Available != nil {
		if _, err := s.PG.Exec(r.Context(), `UPDATE app_user SET available=$1 WHERE id=$2`, *req.Available, req.UserID); err != nil {
			writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}
	}
	if req.Password != "" {
		hash, err := auth.HashPassword(req.Password)
		if err != nil {
			writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}
		if _, err := s.PG.Exec(r.Context(), `UPDATE app_user SET password_hash=$1 WHERE id=$2`, hash, req.UserID); err != nil {
			writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}
	}
	uid := r.Context().Value(ctxUserID).(string)
	role := r.Context().Value(ctxUserRole).(string)
	s.Audit.Record(r.Context(), uid, string(role), "update_user_access", "user", req.UserID, true, map[string]any{"changes": req})

	out := userEnvelope{}
	out.Data.UserID = req.UserID
	out.Data.Username = existing.Username
	out.Data.FullName = existing.FullName
	if len(req.Roles) > 0 {
		out.Data.Roles = req.Roles
	} else {
		out.Data.Roles = splitComma(rolesRaw)
	}
	if len(out.Data.Roles) > 0 {
		out.Data.ActiveRole = out.Data.Roles[0]
	}
	if req.AssignedNodeID != "" {
		out.Data.AssignedNodeID = req.AssignedNodeID
	} else {
		out.Data.AssignedNodeID = existing.AssignedNode
	}
	if req.AssignedLabID != "" {
		out.Data.AssignedLabID = req.AssignedLabID
	} else {
		out.Data.AssignedLabID = existing.AssignedLab
	}
	if len(req.Certifications) > 0 {
		out.Data.Certifications = req.Certifications
	} else {
		out.Data.Certifications = splitComma(certsRaw)
	}
	if req.Available != nil {
		out.Data.Available = *req.Available
	} else {
		out.Data.Available = existing.Available
	}
	writeJSON(w, http.StatusCreated, out)
}

