package httpapi

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"errors"
	"net/http"
	"strings"

	"github.com/go-chi/chi/v5"
	"github.com/jackc/pgx/v5"
	"github.com/lablogistics/models"
)

// randID is a small helper for unique-ish identifiers.
func randID() string {
	b := make([]byte, 8)
	_, _ = rand.Read(b)
	return hex.EncodeToString(b)
}

func chiURLParam(r *http.Request, k string) string {
	return chi.URLParam(r, k)
}

func pgTextArr(in []string) []string {
	out := make([]string, len(in))
	copy(out, in)
	return out
}

// pqStrArr returns a *[]string that pgx will fill from a TEXT[] column.
func pqStrArr(dst *[]string) any {
	return dst
}

func isUniqueViolation(err error) bool {
	if err == nil {
		return false
	}
	return strings.Contains(err.Error(), "duplicate key") || strings.Contains(err.Error(), "unique constraint") || strings.Contains(err.Error(), "23505")
}

func isFKViolation(err error) bool {
	if err == nil {
		return false
	}
	return strings.Contains(err.Error(), "23503") || strings.Contains(err.Error(), "foreign key")
}

// nullJSON handles JSON-encoded details columns.
func nullJSON(v any) any {
	if v == nil {
		return []byte("{}")
	}
	b, err := json.Marshal(v)
	if err != nil {
		return []byte("{}")
	}
	return string(b)
}

// loadUser is a convenience method.
func (s *Server) loadUser(ctx context.Context, id string) (models.User, error) {
	var u models.User
	var rolesRaw, certsRaw string
	if err := s.PG.QueryRow(ctx, `SELECT id, username, password_hash, full_name, array_to_string(roles, ','), active_role, assigned_node, assigned_lab, array_to_string(certifications, ','), available, created_at FROM app_user WHERE id=$1`, id).Scan(&u.ID, &u.Username, &u.PasswordHash, &u.FullName, &rolesRaw, &u.ActiveRole, &u.AssignedNode, &u.AssignedLab, &certsRaw, &u.Available, &u.CreatedAt); err != nil {
		return u, err
	}
	for _, p := range strings.Split(rolesRaw, ",") {
		if p = strings.TrimSpace(p); p != "" {
			u.Roles = append(u.Roles, models.Role(p))
		}
	}
	for _, p := range strings.Split(certsRaw, ",") {
		if p = strings.TrimSpace(p); p != "" {
			u.Certs = append(u.Certs, p)
		}
	}
	u.AssignedNode = u.AssignedNode
	u.AssignedLab = u.AssignedLab
	return u, nil
}

var ErrNotFound = errors.New("not found")

// ctx helper to load first by ID.
func (s *Server) loadLocation(ctx context.Context, id string) (models.Location, error) {
	var l models.Location
	var acceptedRaw string
	if err := s.PG.QueryRow(ctx, `SELECT id, name, latitude, longitude, coverage_km, handling_min, active, is_collection_point, is_transfer_point, is_hub, is_laboratory, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units, array_to_string(accepted_sample_types, ',') FROM location WHERE id=$1`, id).Scan(
		&l.ID, &l.Name, &l.Coordinate.Latitude, &l.Coordinate.Longitude, &l.CoverageKm, &l.HandlingMin, &l.Active,
		&l.Functions.CollectionPoint, &l.Functions.TransferPoint, &l.Functions.Hub, &l.Functions.Laboratory,
		&l.Capacity.CapacityUnits, &l.Capacity.ReservedUnits, &l.Capacity.CooledCapacityUnits, &l.Capacity.CooledReservedUnits, &acceptedRaw,
	); err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return l, ErrNotFound
		}
		return l, err
	}
	l.AcceptedSampleTypes = splitComma(acceptedRaw)
	l.Capacity.AvailableUnits = l.Capacity.CapacityUnits - l.Capacity.ReservedUnits
	l.Capacity.CooledAvailableUnits = l.Capacity.CooledCapacityUnits - l.Capacity.CooledReservedUnits
	return l, nil
}

