package httpapi

import (
	"net/http"

	"github.com/lablogistics/models"
)

type locationEnvelope struct {
	Data locationData `json:"data"`
}

type locationData struct {
	LocationID          string                  `json:"locationId"`
	Name                string                  `json:"name"`
	Coordinate          models.Coordinate       `json:"coordinate"`
	CoverageKm          float64                 `json:"coverageKm"`
	HandlingMinutes     int                     `json:"handlingMinutes"`
	Active              bool                    `json:"active"`
	Functions           models.LocationFunctionStates `json:"functions"`
	Capacity            models.Capacity         `json:"capacity"`
	AcceptedSampleTypeIDs []string              `json:"acceptedSampleTypeIds"`
}

type createLocationReq struct {
	Name                string                       `json:"name"`
	Coordinate          models.Coordinate            `json:"coordinate"`
	CoverageKm          float64                      `json:"coverageKm"`
	HandlingMinutes     int                          `json:"handlingMinutes"`
	Functions           models.LocationFunctionStates `json:"functions"`
	CapacityUnits       int                          `json:"capacityUnits"`
	CooledCapacityUnits int                          `json:"cooledCapacityUnits"`
	AcceptedSampleTypeIDs []string                   `json:"acceptedSampleTypeIds"`
}

func (s *Server) handleCreateLocation(w http.ResponseWriter, r *http.Request) {
	var req createLocationReq
	if err := readJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if req.Name == "" {
		writeError(w, http.StatusBadRequest, "invalid_json", "name required")
		return
	}
	if !req.Functions.CollectionPoint && !req.Functions.TransferPoint && !req.Functions.Hub && !req.Functions.Laboratory {
		writeError(w, http.StatusBadRequest, "invalid_json", "at least one function required")
		return
	}
	id := "loc_" + randID()
	if req.CoverageKm <= 0 {
		req.CoverageKm = 5
	}
	if _, err := s.PG.Exec(r.Context(), `INSERT INTO location (id, name, latitude, longitude, coverage_km, handling_min, active, is_collection_point, is_transfer_point, is_hub, is_laboratory, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units, accepted_sample_types) VALUES ($1,$2,$3,$4,$5,$6,TRUE,$7,$8,$9,$10,$11,0,$12,0,$13)`,
		id, req.Name, req.Coordinate.Latitude, req.Coordinate.Longitude, req.CoverageKm, req.HandlingMinutes,
		req.Functions.CollectionPoint, req.Functions.TransferPoint, req.Functions.Hub, req.Functions.Laboratory,
		req.CapacityUnits, req.CooledCapacityUnits, pgTextArr(req.AcceptedSampleTypeIDs)); err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	uid := r.Context().Value(ctxUserID).(string)
	role := r.Context().Value(ctxUserRole).(string)
	s.Audit.Record(r.Context(), uid, string(role), "create_location", "location", id, true, req)

	// recompute serviceability
	go s.Serv.PublishNewSnapshot(s.ctx())

	out := locationEnvelope{}
	out.Data.LocationID = id
	out.Data.Name = req.Name
	out.Data.Coordinate = req.Coordinate
	out.Data.CoverageKm = req.CoverageKm
	out.Data.HandlingMinutes = req.HandlingMinutes
	out.Data.Active = true
	out.Data.Functions = req.Functions
	out.Data.Capacity = models.Capacity{
		CapacityUnits: req.CapacityUnits, ReservedUnits: 0, AvailableUnits: req.CapacityUnits,
		CooledCapacityUnits: req.CooledCapacityUnits, CooledReservedUnits: 0, CooledAvailableUnits: req.CooledCapacityUnits,
	}
	out.Data.AcceptedSampleTypeIDs = req.AcceptedSampleTypeIDs
	writeJSON(w, http.StatusCreated, out)
}

type updateLocationReq struct {
	LocationID          string                       `json:"locationId"`
	Name                *string                      `json:"name"`
	CoverageKm          *float64                     `json:"coverageKm"`
	HandlingMinutes     *int                         `json:"handlingMinutes"`
	Functions           *models.LocationFunctionStates `json:"functions"`
	CapacityUnits       *int                         `json:"capacityUnits"`
	CooledCapacityUnits *int                         `json:"cooledCapacityUnits"`
	AcceptedSampleTypeIDs *[]string                  `json:"acceptedSampleTypeIds"`
}

func (s *Server) handleUpdateLocation(w http.ResponseWriter, r *http.Request) {
	var req updateLocationReq
	if err := readJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if req.LocationID == "" {
		writeError(w, http.StatusBadRequest, "invalid_json", "locationId required")
		return
	}
	loc, err := s.loadLocation(r.Context(), req.LocationID)
	if err != nil {
		writeError(w, http.StatusNotFound, "location_not_found", "location not found")
		return
	}
	if req.Name != nil {
		loc.Name = *req.Name
	}
	if req.CoverageKm != nil {
		loc.CoverageKm = *req.CoverageKm
	}
	if req.HandlingMinutes != nil {
		loc.HandlingMin = *req.HandlingMinutes
	}
	if req.Functions != nil {
		loc.Functions = *req.Functions
	}
	if req.CapacityUnits != nil {
		loc.Capacity.CapacityUnits = *req.CapacityUnits
		loc.Capacity.AvailableUnits = loc.Capacity.CapacityUnits - loc.Capacity.ReservedUnits
	}
	if req.CooledCapacityUnits != nil {
		loc.Capacity.CooledCapacityUnits = *req.CooledCapacityUnits
		loc.Capacity.CooledAvailableUnits = loc.Capacity.CooledCapacityUnits - loc.Capacity.CooledReservedUnits
	}
	if req.AcceptedSampleTypeIDs != nil {
		loc.AcceptedSampleTypes = *req.AcceptedSampleTypeIDs
	}
	_, err = s.PG.Exec(r.Context(), `UPDATE location SET name=$1, latitude=$2, longitude=$3, coverage_km=$4, handling_min=$5, is_collection_point=$6, is_transfer_point=$7, is_hub=$8, is_laboratory=$9, capacity_units=$10, cooled_capacity_units=$11, accepted_sample_types=$12 WHERE id=$13`,
		loc.Name, loc.Coordinate.Latitude, loc.Coordinate.Longitude, loc.CoverageKm, loc.HandlingMin,
		loc.Functions.CollectionPoint, loc.Functions.TransferPoint, loc.Functions.Hub, loc.Functions.Laboratory,
		loc.Capacity.CapacityUnits, loc.Capacity.CooledCapacityUnits, pgTextArr(loc.AcceptedSampleTypes), loc.ID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	uid := r.Context().Value(ctxUserID).(string)
	role := r.Context().Value(ctxUserRole).(string)
	s.Audit.Record(r.Context(), uid, string(role), "update_location", "location", loc.ID, true, req)
	go s.Serv.PublishNewSnapshot(s.ctx())

	out := locationEnvelope{}
	out.Data.LocationID = loc.ID
	out.Data.Name = loc.Name
	out.Data.Coordinate = loc.Coordinate
	out.Data.CoverageKm = loc.CoverageKm
	out.Data.HandlingMinutes = loc.HandlingMin
	out.Data.Active = loc.Active
	out.Data.Functions = loc.Functions
	out.Data.Capacity = loc.Capacity
	out.Data.AcceptedSampleTypeIDs = loc.AcceptedSampleTypes
	writeJSON(w, http.StatusCreated, out)
}

type setLocationStatusReq struct {
	LocationID string `json:"locationId"`
	Active     bool   `json:"active"`
}

func (s *Server) handleSetLocationStatus(w http.ResponseWriter, r *http.Request) {
	var req setLocationStatusReq
	if err := readJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if req.LocationID == "" {
		writeError(w, http.StatusBadRequest, "invalid_json", "locationId required")
		return
	}
	tag, err := s.PG.Exec(r.Context(), `UPDATE location SET active=$1 WHERE id=$2`, req.Active, req.LocationID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if tag == 0 {
		writeError(w, http.StatusNotFound, "location_not_found", "location not found")
		return
	}
	uid := r.Context().Value(ctxUserID).(string)
	role := r.Context().Value(ctxUserRole).(string)
	s.Audit.Record(r.Context(), uid, string(role), "set_location_status", "location", req.LocationID, true, req)
	go s.Serv.PublishNewSnapshot(s.ctx())
	writeJSON(w, http.StatusOK, map[string]any{"data": map[string]any{"locationId": req.LocationID, "active": req.Active}})
}

type setLocationFunctionStatusReq struct {
	LocationID string `json:"locationId"`
	Function   string `json:"function"`
	Active     bool   `json:"active"`
}

func (s *Server) handleSetLocationFunctionStatus(w http.ResponseWriter, r *http.Request) {
	var req setLocationFunctionStatusReq
	if err := readJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if req.LocationID == "" || req.Function == "" {
		writeError(w, http.StatusBadRequest, "invalid_json", "locationId and function required")
		return
	}
	var col string
	switch req.Function {
	case "collection_point":
		col = "is_collection_point"
	case "transfer_point":
		col = "is_transfer_point"
	case "hub":
		col = "is_hub"
	case "laboratory":
		col = "is_laboratory"
	default:
		writeError(w, http.StatusBadRequest, "invalid_function", "unknown function")
		return
	}
	tag, err := s.PG.Exec(r.Context(), "UPDATE location SET "+col+"=$1 WHERE id=$2", req.Active, req.LocationID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if tag == 0 {
		writeError(w, http.StatusNotFound, "location_not_found", "location not found")
		return
	}
	uid := r.Context().Value(ctxUserID).(string)
	role := r.Context().Value(ctxUserRole).(string)
	s.Audit.Record(r.Context(), uid, string(role), "set_location_function_status", "location", req.LocationID, true, req)
	go s.Serv.PublishNewSnapshot(s.ctx())
	writeJSON(w, http.StatusOK, map[string]any{"data": map[string]any{"locationId": req.LocationID, "function": req.Function, "active": req.Active}})
}

type connectionEnvelope struct {
	Data connectionData `json:"data"`
}

type connectionData struct {
	ConnectionID    string          `json:"connectionId"`
	FromLocationID  string          `json:"fromLocationId"`
	ToLocationID    string          `json:"toLocationId"`
	TravelMinutes   int             `json:"travelMinutes"`
	CostUnits       float64         `json:"costUnits"`
	Cooled          bool            `json:"cooled"`
	Active          bool            `json:"active"`
	Capacity        models.Capacity `json:"capacity"`
}

type createConnectionReq struct {
	FromLocationID      string  `json:"fromLocationId"`
	ToLocationID        string  `json:"toLocationId"`
	TravelMinutes       int     `json:"travelMinutes"`
	CostUnits           float64 `json:"costUnits"`
	Cooled              bool    `json:"cooled"`
	CapacityUnits       int     `json:"capacityUnits"`
	CooledCapacityUnits int     `json:"cooledCapacityUnits"`
}

func (s *Server) handleCreateConnection(w http.ResponseWriter, r *http.Request) {
	var req createConnectionReq
	if err := readJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if req.FromLocationID == "" || req.ToLocationID == "" {
		writeError(w, http.StatusBadRequest, "invalid_json", "from/to required")
		return
	}
	if req.FromLocationID == req.ToLocationID {
		writeError(w, http.StatusBadRequest, "invalid_json", "from and to cannot match")
		return
	}
	id := "con_" + randID()
	_, err := s.PG.Exec(r.Context(), `INSERT INTO connection (id, from_loc, to_loc, travel_min, cost_units, cooled, active, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units) VALUES ($1,$2,$3,$4,$5,$6,TRUE,$7,0,$8,0)`,
		id, req.FromLocationID, req.ToLocationID, req.TravelMinutes, req.CostUnits, req.Cooled, req.CapacityUnits, req.CooledCapacityUnits)
	if err != nil {
		if isFKViolation(err) {
			writeError(w, http.StatusConflict, "unknown_location", "from/to location does not exist")
			return
		}
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	uid := r.Context().Value(ctxUserID).(string)
	role := r.Context().Value(ctxUserRole).(string)
	s.Audit.Record(r.Context(), uid, string(role), "create_connection", "connection", id, true, req)
	go s.Serv.PublishNewSnapshot(s.ctx())

	out := connectionEnvelope{}
	out.Data.ConnectionID = id
	out.Data.FromLocationID = req.FromLocationID
	out.Data.ToLocationID = req.ToLocationID
	out.Data.TravelMinutes = req.TravelMinutes
	out.Data.CostUnits = req.CostUnits
	out.Data.Cooled = req.Cooled
	out.Data.Active = true
	out.Data.Capacity = models.Capacity{
		CapacityUnits: req.CapacityUnits, ReservedUnits: 0, AvailableUnits: req.CapacityUnits,
		CooledCapacityUnits: req.CooledCapacityUnits, CooledReservedUnits: 0, CooledAvailableUnits: req.CooledCapacityUnits,
	}
	writeJSON(w, http.StatusCreated, out)
}

type setConnectionStatusReq struct {
	ConnectionID string `json:"connectionId"`
	Active       bool   `json:"active"`
}

func (s *Server) handleSetConnectionStatus(w http.ResponseWriter, r *http.Request) {
	var req setConnectionStatusReq
	if err := readJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if req.ConnectionID == "" {
		writeError(w, http.StatusBadRequest, "invalid_json", "connectionId required")
		return
	}
	tag, err := s.PG.Exec(r.Context(), `UPDATE connection SET active=$1 WHERE id=$2`, req.Active, req.ConnectionID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if tag == 0 {
		writeError(w, http.StatusNotFound, "connection_not_found", "connection not found")
		return
	}
	uid := r.Context().Value(ctxUserID).(string)
	role := r.Context().Value(ctxUserRole).(string)
	s.Audit.Record(r.Context(), uid, string(role), "set_connection_status", "connection", req.ConnectionID, true, req)
	go s.Serv.PublishNewSnapshot(s.ctx())
	writeJSON(w, http.StatusOK, map[string]any{"data": map[string]any{"connectionId": req.ConnectionID, "active": req.Active}})
}

type configureCapacityReq struct {
	Target               string `json:"target"` // "location:<id>" or "connection:<id>"
	RegularCapacityUnits *int   `json:"regularCapacityUnits"`
	CooledCapacityUnits  *int   `json:"cooledCapacityUnits"`
}

func (s *Server) handleConfigureCapacity(w http.ResponseWriter, r *http.Request) {
	var req configureCapacityReq
	if err := readJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if req.Target == "" {
		writeError(w, http.StatusBadRequest, "invalid_json", "target required")
		return
	}
	if req.RegularCapacityUnits == nil && req.CooledCapacityUnits == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "regularCapacityUnits or cooledCapacityUnits required")
		return
	}
	parts := splitColon(req.Target)
	if len(parts) != 2 {
		writeError(w, http.StatusBadRequest, "invalid_target", "target must be 'location:<id>' or 'connection:<id>'")
		return
	}
	kind, id := parts[0], parts[1]
	uid := r.Context().Value(ctxUserID).(string)
	role := r.Context().Value(ctxUserRole).(string)
	switch kind {
	case "location":
		updates := []string{}
		args := []any{}
		if req.RegularCapacityUnits != nil {
			updates = append(updates, "capacity_units=$1")
			args = append(args, *req.RegularCapacityUnits)
		}
		if req.CooledCapacityUnits != nil {
			if len(updates) == 0 {
				updates = append(updates, "cooled_capacity_units=$1")
				args = append(args, *req.CooledCapacityUnits)
			} else {
				updates = append(updates, fmt.Sprintf("cooled_capacity_units=$%d", len(args)+1))
				args = append(args, *req.CooledCapacityUnits)
			}
		}
		args = append(args, id)
		tag, err := s.PG.Exec(r.Context(), "UPDATE location SET "+strings.Join(updates, ", ")+" WHERE id=$"+itoa(len(args)), args...)
		if err != nil {
			writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}
		if tag == 0 {
			writeError(w, http.StatusNotFound, "location_not_found", "location not found")
			return
		}
	case "connection":
		updates := []string{}
		args := []any{}
		if req.RegularCapacityUnits != nil {
			updates = append(updates, "capacity_units=$1")
			args = append(args, *req.RegularCapacityUnits)
		}
		if req.CooledCapacityUnits != nil {
			if len(updates) == 0 {
				updates = append(updates, "cooled_capacity_units=$1")
				args = append(args, *req.CooledCapacityUnits)
			} else {
				updates = append(updates, fmt.Sprintf("cooled_capacity_units=$%d", len(args)+1))
				args = append(args, *req.CooledCapacityUnits)
			}
		}
		args = append(args, id)
