		return
	}
	if req.LocationID == "" {
		writeError(w, http.StatusBadRequest, "invalid_json", "locationId required")
		return
	}
	loc, err := s.loadLocation(r.Context(), req.LocationID)
	if err != nil {
		writeError(w, http.StatusNotFound, "location_not_found", "location not found")
		return
	}
	if req.Name != nil {
		loc.Name = *req.Name
	}
	if req.CoverageKm != nil {
		loc.CoverageKm = *req.CoverageKm
	}
	if req.HandlingMinutes != nil {
		loc.HandlingMin = *req.HandlingMinutes
	}
	if req.Functions != nil {
		loc.Functions = *req.Functions
	}
	if req.CapacityUnits != nil {
		loc.Capacity.CapacityUnits = *req.CapacityUnits
		loc.Capacity.AvailableUnits = loc.Capacity.CapacityUnits - loc.Capacity.ReservedUnits
	}
	if req.CooledCapacityUnits != nil {
		loc.Capacity.CooledCapacityUnits = *req.CooledCapacityUnits
		loc.Capacity.CooledAvailableUnits = loc.Capacity.CooledCapacityUnits - loc.Capacity.CooledReservedUnits
	}
	if req.AcceptedSampleTypeIDs != nil {
		loc.AcceptedSampleTypes = *req.AcceptedSampleTypeIDs
	}
	_, err = s.PG.Exec(r.Context(), `UPDATE location SET name=$1, latitude=$2, longitude=$3, coverage_km=$4, handling_min=$5, is_collection_point=$6, is_transfer_point=$7, is_hub=$8, is_laboratory=$9, capacity_units=$10, cooled_capacity_units=$11, accepted_sample_types=$12 WHERE id=$13`,
		loc.Name, loc.Coordinate.Latitude, loc.Coordinate.Longitude, loc.CoverageKm, loc.HandlingMin,
		loc.Functions.CollectionPoint, loc.Functions.TransferPoint, loc.Functions.Hub, loc.Functions.Laboratory,
		loc.Capacity.CapacityUnits, loc.Capacity.CooledCapacityUnits, pgTextArr(loc.AcceptedSampleTypes), loc.ID)
