		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	uid := r.Context().Value(ctxUserID).(string)
	role := r.Context().Value(ctxUserRole).(string)
	s.Audit.Record(r.Context(), uid, string(role), "update_location", "location", loc.ID, true, req)
	go s.Serv.PublishNewSnapshot(s.ctx())

	out := locationEnvelope{}
	out.Data.LocationID = loc.ID
	out.Data.Name = loc.Name
	out.Data.Coordinate = loc.Coordinate
	out.Data.CoverageKm = loc.CoverageKm
	out.Data.HandlingMinutes = loc.HandlingMin
	out.Data.Active = loc.Active
	out.Data.Functions = loc.Functions
	out.Data.Capacity = loc.Capacity
	out.Data.AcceptedSampleTypeIDs = loc.AcceptedSampleTypes
	writeJSON(w, http.StatusCreated, out)
}

