	Target               string `json:"target"` // "location:<id>" or "connection:<id>"
	RegularCapacityUnits *int   `json:"regularCapacityUnits"`
	CooledCapacityUnits  *int   `json:"cooledCapacityUnits"`
}

func (s *Server) handleConfigureCapacity(w http.ResponseWriter, r *http.Request) {
	var req configureCapacityReq
	if err := readJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if req.Target == "" {
		writeError(w, http.StatusBadRequest, "invalid_json", "target required")
		return
	}
	if req.RegularCapacityUnits == nil && req.CooledCapacityUnits == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "regularCapacityUnits or cooledCapacityUnits required")
		return
	}
	parts := splitColon(req.Target)
	if len(parts) != 2 {
		writeError(w, http.StatusBadRequest, "invalid_target", "target must be 'location:<id>' or 'connection:<id>'")
		return
	}
	kind, id := parts[0], parts[1]
	uid := r.Context().Value(ctxUserID).(string)
	role := r.Context().Value(ctxUserRole).(string)
	switch kind {
	case "location":
		updates := []string{}
		args := []any{}
		if req.RegularCapacityUnits != nil {
			updates = append(updates, "capacity_units=$1")
			args = append(args, *req.RegularCapacityUnits)
		}
		if req.CooledCapacityUnits != nil {
			if len(updates) == 0 {
				updates = append(updates, "cooled_capacity_units=$1")
				args = append(args, *req.CooledCapacityUnits)
			} else {
				updates = append(updates, fmt.Sprintf("cooled_capacity_units=$%d", len(args)+1))
				args = append(args, *req.CooledCapacityUnits)
			}
		}
		args = append(args, id)
		tag, err := s.PG.Exec(r.Context(), "UPDATE location SET "+strings.Join(updates, ", ")+" WHERE id=$"+itoa(len(args)), args...)
		if err != nil {
			writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}
		if tag == 0 {
			writeError(w, http.StatusNotFound, "location_not_found", "location not found")
			return
		}
	case "connection":
		updates := []string{}
		args := []any{}
		if req.RegularCapacityUnits != nil {
			updates = append(updates, "capacity_units=$1")
			args = append(args, *req.RegularCapacityUnits)
		}
		if req.CooledCapacityUnits != nil {
			if len(updates) == 0 {
				updates = append(updates, "cooled_capacity_units=$1")
				args = append(args, *req.CooledCapacityUnits)
			} else {
				updates = append(updates, fmt.Sprintf("cooled_capacity_units=$%d", len(args)+1))
				args = append(args, *req.CooledCapacityUnits)
			}
		}
		args = append(args, id)
		tag, err := s.PG.Exec(r.Context(), "UPDATE connection SET "+strings.Join(updates, ", ")+" WHERE id=$"+itoa(len(args)), args...)
		if err != nil {
			writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}
		if tag == 0 {
			writeError(w, http.StatusNotFound, "connection_not_found", "connection not found")
			return
		}
	default:
		writeError(w, http.StatusBadRequest, "invalid_target", "unknown target kind")
		return
	}
	s.Audit.Record(r.Context(), uid, string(role), "configure_capacity", kind, id, true, req)
	go s.Serv.PublishNewSnapshot(s.ctx())
	writeJSON(w, http.StatusOK, map[string]any{"data": req})
}

