	if _, err := tx.Exec(r.Context(), `INSERT INTO request (id, requester_id, origin_type, origin_node_id, origin_lat, origin_lon, sample_type_id, earliest_collection, latest_collection, delivery_deadline, target_lab_id, status, created_at) VALUES ($1,$2,'node',$3,$4,$5,$6,$7,$8,$9,$10,'open',$11)`,
		reqID, uid, req.OriginNodeID, nodeLat, nodeLon, st.ID, req.EarliestCollection, req.LatestCollection, req.DeliveryDeadline, req.TargetLaboratoryID, now); err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	container := req.ContainerType
	if container == "" {
		container = st.ContainerType
	}
	if _, err := tx.Exec(r.Context(), `INSERT INTO sample (id, request_id, requester_id, origin_type, origin_node_id, origin_lat, origin_lon, sample_type_id, container_type, temp_min_c, temp_max_c, incompatible_types, serviceability, requested_at, earliest_collection, latest_collection, delivery_deadline, sealed, status, current_holder_id, current_lat, current_lon, location_at, target_lab_id, active_journey_id, active_assignments, exception) VALUES ($1,$2,$3,'node',$4,$5,$6,$7,$8,$9,$10,$11,'serviceable',$12,$13,$14,$15,TRUE,'in_transit',$16,$17,$18,$19,$20,$21,ARRAY[$22]::text[], CASE WHEN $23 < temp_min_c OR $23 > temp_max_c THEN 'temperature_out_of_range' ELSE '' END)`,
		sampleID, reqID, uid, req.OriginNodeID, nodeLat, nodeLon, st.ID, container, st.TempMinC, st.TempMaxC,
		pgTextArr(st.IncompatibleWith), now, req.EarliestCollection, req.LatestCollection, req.DeliveryDeadline,
		uid, nodeLat, nodeLon, now, req.TargetLaboratoryID, journeyID, assignID, req.ObservedTemperature); err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if _, err := tx.Exec(r.Context(), `INSERT INTO journey (id, plan_version, route_mode, status, estimated_delivery, total_cost, capacity_used, capacity_available, sample_ids, valid) VALUES ($1,1,'direct','active',$2,0,1,1,$3,TRUE)`,
		journeyID, req.DeliveryDeadline, []string{sampleID}); err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if _, err := tx.Exec(r.Context(), `INSERT INTO journey_stop (id, journey_id, location_id, stop_type, sequence, estimated_at, dwell_min) VALUES ('stp_'||$1,$2,$3,'pickup',0,$4,0)`, randID(), journeyID, req.OriginNodeID, now); err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if _, err := tx.Exec(r.Context(), `INSERT INTO journey_stop (id, journey_id, location_id, stop_type, sequence, estimated_at, dwell_min) VALUES ('stp_'||$1,$2,$3,'delivery',1,$4,0)`, randID(), journeyID, req.TargetLaboratoryID, req.DeliveryDeadline); err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
