package httpapi

import (
	"net/http"
	"time"

	"github.com/lablogistics/models"
)

type readSampleLifecycleReq struct {
	SampleID string `json:"sampleId"`
}

type readSampleLifecycleEnvelope struct {
	Data sampleLifecycleData `json:"data"`
}

type sampleLifecycleData struct {
	SampleID   string                  `json:"sampleId"`
	Timeline   []models.TimelineEvent  `json:"timeline"`
	Sample     map[string]any          `json:"sample"`
}

func (s *Server) handleReadSampleLifecycle(w http.ResponseWriter, r *http.Request) {
	var req readSampleLifecycleReq
	if err := readJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if req.SampleID == "" {
		writeError(w, http.StatusBadRequest, "invalid_json", "sampleId required")
		return
	}
	evs, err := s.Audit.Timeline(r.Context(), req.SampleID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	out := readSampleLifecycleEnvelope{}
	out.Data.SampleID = req.SampleID
	out.Data.Timeline = evs
	out.Data.Sample = sampleAsMap(r.Context(), s.PG, req.SampleID)
	writeJSON(w, http.StatusOK, out)
}

type sampleStateEnvelope struct {
	Data map[string]any `json:"data"`
}

func (s *Server) handleReadSampleState(w http.ResponseWriter, r *http.Request) {
	id := chiURLParam(r, "sampleId")
	if id == "" {
		writeError(w, http.StatusBadRequest, "invalid_id", "sampleId required")
		return
	}
	out := sampleStateEnvelope{Data: sampleAsMap(r.Context(), s.PG, id)}
	if out.Data == nil {
		writeError(w, http.StatusNotFound, "sample_not_found", "sample not found")
		return
	}
	writeJSON(w, http.StatusOK, out)
}

type readJourneyPlanReq struct {
	JourneyID string `json:"journeyId"`
}

type readJourneyPlanEnvelope struct {
	Data journeyPlanData `json:"data"`
}

type journeyPlanData struct {
	JourneyID        string              `json:"journeyId"`
	PlanVersion      int                 `json:"planVersion"`
	Status           string              `json:"status"`
	EstimatedDelivery time.Time          `json:"estimatedDeliveryAt"`
	Stops            []models.JourneyStop `json:"stops"`
	Assignments      []assignmentData    `json:"assignments"`
}

func (s *Server) handleReadJourneyPlan(w http.ResponseWriter, r *http.Request) {
	var req readJourneyPlanReq
	if err := readJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if req.JourneyID == "" {
		writeError(w, http.StatusBadRequest, "invalid_json", "journeyId required")
		return
	}
	var j models.Journey
	var samplesRaw string
	if err := s.PG.QueryRow(r.Context(), `SELECT id, plan_version, status, estimated_delivery, array_to_string(sample_ids, ',') FROM journey WHERE id=$1`, req.JourneyID).Scan(&j.ID, &j.PlanVersion, &j.Status, &j.EstimatedDelivery, &samplesRaw); err != nil {
		writeError(w, http.StatusNotFound, "journey_not_found", "journey not found")
		return
	}
	j.SampleIDs = splitComma(samplesRaw)
	rows, err := s.PG.Query(r.Context(), `SELECT id, journey_id, location_id, stop_type, sequence, estimated_at, dwell_min, completed_at FROM journey_stop WHERE journey_id=$1 ORDER BY sequence ASC`, req.JourneyID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	defer rows.Close()
	var stops []models.JourneyStop
	for rows.Next() {
		var st models.JourneyStop
		if err := rows.Scan(&st.ID, &st.JourneyID, &st.LocationID, &st.StopType, &st.Sequence, &st.EstimatedAt, &st.DwellMinutes, &st.CompletedAt); err != nil {
			writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}
		stops = append(stops, st)
	}
	if stops == nil {
		stops = []models.JourneyStop{}
	}
	rows2, err := s.PG.Query(r.Context(), `SELECT id, journey_id, sample_id, kind, sequence, from_location_id, to_location_id, worker_id, status, offer_expires_at, offered_at, resolves_capacity, uses_cooled FROM assignment WHERE journey_id=$1 ORDER BY sequence ASC`, req.JourneyID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	defer rows2.Close()
	var asgs []assignmentData
	for rows2.Next() {
		var a models.Assignment
		if err := rows2.Scan(&a.ID, &a.JourneyID, &a.SampleID, &a.Kind, &a.Sequence, &a.FromLocationID, &a.ToLocationID, &a.WorkerID, &a.Status, &a.OfferExpiresAt, &a.OfferedAt, &a.ResolvesCapacity, &a.UsesCooled); err != nil {
			writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}
		asgs = append(asgs, serializeAssignment(a))
	}
	if asgs == nil {
		asgs = []assignmentData{}
	}
	out := readJourneyPlanEnvelope{}
	out.Data.JourneyID = j.ID
	out.Data.PlanVersion = j.PlanVersion
	out.Data.Status = j.Status
	out.Data.EstimatedDelivery = j.EstimatedDelivery
	out.Data.Stops = stops
	out.Data.Assignments = asgs
	writeJSON(w, http.StatusOK, out)
}

// --- search audit trail -------------------------------------------------

type searchAuditReq struct {
	ActorID     string    `json:"actorId"`
	Role        string    `json:"role"`
	Action      string    `json:"action"`
	EntityType  string    `json:"entityType"`
	EntityID    string    `json:"entityId"`
	Since       time.Time `json:"since"`
	Until       time.Time `json:"until"`
}

type searchAuditEnvelope struct {
	Data searchAuditData `json:"data"`
}

type searchAuditData struct {
	Entries []models.AuditEntry `json:"entries"`
}

func (s *Server) handleSearchAuditTrail(w http.ResponseWriter, r *http.Request) {
	var req searchAuditReq
	if err := readJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	entries, err := s.Audit.SearchAudit(r.Context(), req.ActorID, req.Role, req.Action, req.EntityType, req.EntityID, req.Since, req.Until)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	out := searchAuditEnvelope{}
	out.Data.Entries = entries
	writeJSON(w, http.StatusOK, out)
}

func sampleAsMap(ctx interface{ Done() <-chan struct{} }, pg interface {
	QueryRow(string, ...any) interface{ Scan(...any) error }
}, id string) map[string]any {
	return nil
}

