	out.Data.PlanVersion = j.PlanVersion
	out.Data.Status = j.Status
	out.Data.EstimatedDelivery = j.EstimatedDelivery
	out.Data.Stops = stops
	out.Data.Assignments = asgs
	writeJSON(w, http.StatusOK, out)
