package httpapi

import (
	"net/http"
	"time"

	"github.com/lablogistics/models"
)

// ----- disruption & replanning -----------------------------------------

type reportDisruptionReq struct {
	EntityType string `json:"entityType"` // worker, node, route, laboratory, capacity
	EntityID   string `json:"entityId"`
	Reason     string `json:"reason"`
}

func (s *Server) handleReportDisruption(w http.ResponseWriter, r *http.Request) {
	uid := r.Context().Value(ctxUserID).(string)
	role := r.Context().Value(ctxUserRole).(string)
	var req reportDisruptionReq
	if err := readJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if req.EntityType == "" || req.EntityID == "" {
		writeError(w, http.StatusBadRequest, "invalid_json", "entityType and entityId required")
		return
	}
	// Mark the entity inactive / unavailable depending on type
	switch req.EntityType {
	case "worker":
		_, _ = s.PG.Exec(r.Context(), `UPDATE app_user SET available=FALSE WHERE id=$1`, req.EntityID)
	case "node", "laboratory":
		_, _ = s.PG.Exec(r.Context(), `UPDATE location SET active=FALSE WHERE id=$1`, req.EntityID)
	case "route", "connection":
		_, _ = s.PG.Exec(r.Context(), `UPDATE connection SET active=FALSE WHERE id=$1`, req.EntityID)
	case "capacity":
		// generic capacity: leave alone; auditor can decide.
	default:
		writeError(w, http.StatusBadRequest, "invalid_entity_type", "unknown entityType")
		return
	}
	s.Audit.Record(r.Context(), uid, string(role), "report_disruption", req.EntityType, req.EntityID, true, req)
	go s.Serv.PublishNewSnapshot(s.ctx())
	writeJSON(w, http.StatusCreated, map[string]any{"data": map[string]any{"entityType": req.EntityType, "entityId": req.EntityID, "status": "disruption_recorded"}})
}

type rerouteReq struct {
	JourneyID    string `json:"journeyId"`
	PlanVersion  int    `json:"planVersion"`
	NewRouteMode string `json:"newRouteMode"`
}

func (s *Server) handleRerouteJourney(w http.ResponseWriter, r *http.Request) {
	uid := r.Context().Value(ctxUserID).(string)
	role := r.Context().Value(ctxUserRole).(string)
	var req rerouteReq
	if err := readJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if req.JourneyID == "" {
		writeError(w, http.StatusBadRequest, "invalid_json", "journeyId required")
		return
	}
	var pv int
	if err := s.PG.QueryRow(r.Context(), "SELECT plan_version FROM journey WHERE id=$1", req.JourneyID).Scan(&pv); err != nil {
		writeError(w, http.StatusNotFound, "journey_not_found", "journey not found")
		return
	}
	if req.PlanVersion != 0 && req.PlanVersion != pv {
		writeError(w, http.StatusConflict, "state_snapshot_changed", "plan version stale")
		return
	}
	if _, err := s.PG.Exec(r.Context(), `UPDATE journey SET plan_version=plan_version+1, route_mode=$1 WHERE id=$2`, req.NewRouteMode, req.JourneyID); err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	// Cancel non-completed assignments and re-flag for replanning
	_, _ = s.PG.Exec(r.Context(), `UPDATE assignment SET status='cancelled' WHERE journey_id=$1 AND status IN ('offered','accepted','in_progress')`, req.JourneyID)
	s.Audit.Record(r.Context(), uid, string(role), "reroute_journey", "journey", req.JourneyID, true, req)
	s.Br.Publish("journey.rerouted", "journey", req.JourneyID, map[string]any{"newRouteMode": req.NewRouteMode})
	writeJSON(w, http.StatusCreated, map[string]any{"data": map[string]any{"journeyId": req.JourneyID, "planVersion": pv + 1, "status": "rerouted"}})
}

type cancelJourneyReq struct {
	JourneyID    string `json:"journeyId"`
	PlanVersion  int    `json:"planVersion"`
	Reason       string `json:"reason"`
}

func (s *Server) handleCancelJourney(w http.ResponseWriter, r *http.Request) {
	uid := r.Context().Value(ctxUserID).(string)
	role := r.Context().Value(ctxUserRole).(string)
	var req cancelJourneyReq
	if err := readJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if req.JourneyID == "" {
		writeError(w, http.StatusBadRequest, "invalid_json", "journeyId required")
		return
	}
	var pv int
	if err := s.PG.QueryRow(r.Context(), "SELECT plan_version FROM journey WHERE id=$1", req.JourneyID).Scan(&pv); err != nil {
		writeError(w, http.StatusNotFound, "journey_not_found", "journey not found")
		return
	}
	if req.PlanVersion != 0 && req.PlanVersion != pv {
		writeError(w, http.StatusConflict, "state_snapshot_changed", "plan version stale")
		return
	}
	if _, err := s.PG.Exec(r.Context(), `UPDATE journey SET status='cancelled', valid=FALSE WHERE id=$1`, req.JourneyID); err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	_, _ = s.PG.Exec(r.Context(), `UPDATE assignment SET status='cancelled' WHERE journey_id=$1 AND status IN ('offered','accepted','in_progress')`, req.JourneyID)
	_, _ = s.PG.Exec(r.Context(), `UPDATE sample SET status='cancelled', exception=$1 WHERE active_journey_id=$2 AND status NOT IN ('received')`, req.Reason, req.JourneyID)
	s.Audit.Record(r.Context(), uid, string(role), "cancel_journey", "journey", req.JourneyID, true, req)
	s.Br.Publish("journey.cancelled", "journey", req.JourneyID, map[string]any{"reason": req.Reason})
	writeJSON(w, http.StatusCreated, map[string]any{"data": map[string]any{"journeyId": req.JourneyID, "status": "cancelled"}})
}

type splitJourneyReq struct {
	JourneyID      string   `json:"journeyId"`
	PlanVersion    int      `json:"planVersion"`
	SplitAtSampleIDs []string `json:"splitAtSampleIds"`
}

func (s *Server) handleSplitJourney(w http.ResponseWriter, r *http.Request) {
	uid := r.Context().Value(ctxUserID).(string)
	role := r.Context().Value(ctxUserRole).(string)
	var req splitJourneyReq
	if err := readJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if req.JourneyID == "" || len(req.SplitAtSampleIDs) == 0 {
		writeError(w, http.StatusBadRequest, "invalid_json", "journeyId and splitAtSampleIds required")
		return
	}
	var pv int
	var allSamples []string
	if err := s.PG.QueryRow(r.Context(), "SELECT plan_version, sample_ids FROM journey WHERE id=$1", req.JourneyID).Scan(&pv, &allSamples); err != nil {
		writeError(w, http.StatusNotFound, "journey_not_found", "journey not found")
		return
	}
	if req.PlanVersion != 0 && req.PlanVersion != pv {
		writeError(w, http.StatusConflict, "state_snapshot_changed", "plan version stale")
		return
	}
	keep := []string{}
	split := []string{}
	keepSet := map[string]bool{}
	for _, s := range req.SplitAtSampleIDs {
		keepSet[s] = true
	}
	for _, s := range allSamples {
		if keepSet[s] {
			split = append(split, s)
		} else {
			keep = append(keep, s)
		}
	}
	newID := "jrn_" + randID()
	if _, err := s.PG.Exec(r.Context(), `INSERT INTO journey (id, plan_version, route_mode, status, estimated_delivery, total_cost, capacity_used, capacity_available, sample_ids, parent_journey_id, valid) SELECT $1, plan_version+1, route_mode, status, estimated_delivery, total_cost, capacity_used, capacity_available, $2, id, TRUE FROM journey WHERE id=$3`,
		newID, split, req.JourneyID); err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if _, err := s.PG.Exec(r.Context(), `UPDATE journey SET sample_ids=$1, plan_version=plan_version+1 WHERE id=$2`, keep, req.JourneyID); err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	s.Audit.Record(r.Context(), uid, string(role), "split_journey", "journey", req.JourneyID, true, map[string]any{"newJourneyId": newID, "splitAt": req.SplitAtSampleIDs})
	s.Br.Publish("journey.split", "journey", req.JourneyID, map[string]any{"newJourneyId": newID})
	writeJSON(w, http.StatusCreated, map[string]any{"data": map[string]any{"originalJourneyId": req.JourneyID, "newJourneyId": newID, "planVersion": pv + 1}})
}

type mergeJourneysReq struct {
	JourneyIDs   []string `json:"journeyIds"`
	PlanVersion  int       `json:"planVersion"`
	PrimaryID    string    `json:"primaryJourneyId"`
}

func (s *Server) handleMergeJourneys(w http.ResponseWriter, r *http.Request) {
	uid := r.Context().Value(ctxUserID).(string)
	role := r.Context().Value(ctxUserRole).(string)
	var req mergeJourneysReq
	if err := readJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if len(req.JourneyIDs) < 2 || req.PrimaryID == "" {
		writeError(w, http.StatusBadRequest, "invalid_json", "need at least two journeyIds and a primary")
		return
	}
	var pv int
	if err := s.PG.QueryRow(r.Context(), "SELECT plan_version FROM journey WHERE id=$1", req.PrimaryID).Scan(&pv); err != nil {
		writeError(w, http.StatusNotFound, "journey_not_found", "primary journey not found")
		return
	}
	if req.PlanVersion != 0 && req.PlanVersion != pv {
		writeError(w, http.StatusConflict, "state_snapshot_changed", "plan version stale")
		return
	}
	for _, id := range req.JourneyIDs {
		if id == req.PrimaryID {
			continue
		}
		if _, err := s.PG.Exec(r.Context(), `UPDATE sample SET active_journey_id=$1 WHERE active_journey_id=$2`, req.PrimaryID, id); err != nil {
			writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}
		if _, err := s.PG.Exec(r.Context(), `UPDATE assignment SET journey_id=$1 WHERE journey_id=$2`, req.PrimaryID, id); err != nil {
			writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}
		if _, err := s.PG.Exec(r.Context(), `UPDATE journey SET status='merged' WHERE id=$1`, id); err != nil {
			writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}
	}
	if _, err := s.PG.Exec(r.Context(), `UPDATE journey SET plan_version=plan_version+1 WHERE id=$1`, req.PrimaryID); err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	s.Audit.Record(r.Context(), uid, string(role), "merge_journeys", "journey", req.PrimaryID, true, req)
	s.Br.Publish("journey.merged", "journey", req.PrimaryID, map[string]any{"mergedIds": req.JourneyIDs})
	writeJSON(w, http.StatusCreated, map[string]any{"data": map[string]any{"primaryJourneyId": req.PrimaryID, "mergedIds": req.JourneyIDs, "planVersion": pv + 1}})
}

type editActivePlanReq struct {
	JourneyID    string         `json:"journeyId"`
	PlanVersion  int            `json:"planVersion"`
	Stops        []stopEdit     `json:"stops"`
	Assignments  []assignmentEdit `json:"assignments"`
}

type stopEdit struct {
	Sequence int    `json:"sequence"`
	LocationID string `json:"locationId"`
	StopType string `json:"stopType"`
}

type assignmentEdit struct {
	Sequence int    `json:"sequence"`
	FromLocationID string `json:"fromLocationId"`
	ToLocationID string `json:"toLocationId"`
	WorkerID string `json:"workerId"`
}

func (s *Server) handleEditActivePlan(w http.ResponseWriter, r *http.Request) {
	uid := r.Context().Value(ctxUserID).(string)
	role := r.Context().Value(ctxUserRole).(string)
	var req editActivePlanReq
	if err := readJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	var pv int
	if err := s.PG.QueryRow(r.Context(), "SELECT plan_version FROM journey WHERE id=$1", req.JourneyID).Scan(&pv); err != nil {
		writeError(w, http.StatusNotFound, "journey_not_found", "journey not found")
		return
	}
	if req.PlanVersion != 0 && req.PlanVersion != pv {
		writeError(w, http.StatusConflict, "state_snapshot_changed", "plan version stale")
		return
	}
	// Update stops that haven't been completed yet
	for _, st := range req.Stops {
		_, _ = s.PG.Exec(r.Context(), `UPDATE journey_stop SET location_id=$1, stop_type=$2 WHERE journey_id=$3 AND sequence=$4 AND completed_at IS NULL`,
			st.LocationID, st.StopType, req.JourneyID, st.Sequence)
	}
	for _, asg := range req.Assignments {
		_, _ = s.PG.Exec(r.Context(), `UPDATE assignment SET from_location_id=$1, to_location_id=$2, worker_id=$3 WHERE journey_id=$4 AND sequence=$5 AND status NOT IN ('completed','cancelled','declined')`,
			asg.FromLocationID, asg.ToLocationID, asg.WorkerID, req.JourneyID, asg.Sequence)
	}
	if _, err := s.PG.Exec(r.Context(), `UPDATE journey SET plan_version=plan_version+1 WHERE id=$1`, req.JourneyID); err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	s.Audit.Record(r.Context(), uid, string(role), "edit_active_plan", "journey", req.JourneyID, true, req)
	s.Br.Publish("journey.edited", "journey", req.JourneyID, map[string]any{"planVersion": pv + 1})
	writeJSON(w, http.StatusCreated, map[string]any{"data": map[string]any{"journeyId": req.JourneyID, "planVersion": pv + 1}})
}

// ----- read operations state --------------------------------------------

type operationsStateEnvelope struct {
	Data operationsStateData `json:"data"`
}

type operationsStateData struct {
	Locations     []map[string]any   `json:"locations"`
	Connections   []map[string]any   `json:"connections"`
	Workers       []map[string]any   `json:"workers"`
	SampleSummaries []map[string]any `json:"sampleSummaries"`
	SnapshotVersion int               `json:"snapshotVersion"`
}

func (s *Server) handleReadOperationsState(w http.ResponseWriter, r *http.Request) {
	var req struct {
		IncludeCompleted bool `json:"includeCompleted"`
	}
	_ = readJSON(r, &req)

	locations := []map[string]any{}
	rows, err := s.PG.Query(r.Context(), `SELECT id, name, latitude, longitude, active, is_collection_point, is_transfer_point, is_hub, is_laboratory, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units FROM location`)
	if err == nil {
		defer rows.Close()
		for rows.Next() {
			var id, name string
			var lat, lon float64
			var active, icp, itp, ih, il bool
			var cu, ru, ccu, cru int
			if err := rows.Scan(&id, &name, &lat, &lon, &active, &icp, &itp, &ih, &il, &cu, &ru, &ccu, &cru); err == nil {
				locations = append(locations, map[string]any{
					"locationId": id, "name": name, "coordinate": map[string]any{"latitude": lat, "longitude": lon},
					"active": active,
					"functions": map[string]any{"collection_point": icp, "transfer_point": itp, "hub": ih, "laboratory": il},
					"capacity": map[string]any{
						"capacityUnits": cu, "reservedUnits": ru, "availableUnits": cu - ru,
						"cooledCapacityUnits": ccu, "cooledReservedUnits": cru, "cooledAvailableUnits": ccu - cru,
					},
				})
			}
		}
	}

	connections := []map[string]any{}
	rows2, err := s.PG.Query(r.Context(), `SELECT id, from_loc, to_loc, travel_min, cooled, active, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units FROM connection`)
	if err == nil {
		defer rows2.Close()
		for rows2.Next() {
			var id, f, t string
			var travel int
			var cooled, active bool
			var cu, ru, ccu, cru int
			if err := rows2.Scan(&id, &f, &t, &travel, &cooled, &active, &cu, &ru, &ccu, &cru); err == nil {
				connections = append(connections, map[string]any{
					"connectionId": id, "fromLocationId": f, "toLocationId": t, "travelMinutes": travel,
					"cooled": cooled, "active": active,
					"capacity": map[string]any{
						"capacityUnits": cu, "reservedUnits": ru, "availableUnits": cu - ru,
						"cooledCapacityUnits": ccu, "cooledReservedUnits": cru, "cooledAvailableUnits": ccu - cru,
					},
				})
			}
		}
	}

	workers := []map[string]any{}
	rows3, err := s.PG.Query(r.Context(), `SELECT id, full_name, array_to_string(roles, ','), active_role, available, assigned_node, assigned_lab FROM app_user`)
	if err == nil {
		defer rows3.Close()
		for rows3.Next() {
			var id, name, rolesRaw, activeRole, node, lab string
			var available bool
			if err := rows3.Scan(&id, &name, &rolesRaw, &activeRole, &available, &node, &lab); err == nil {
				workers = append(workers, map[string]any{
					"userId": id, "fullName": name, "roles": splitComma(rolesRaw), "activeRole": activeRole,
					"available": available, "assignedNodeId": node, "assignedLaboratoryId": lab,
				})
			}
		}
	}

	sampleSummaries := []map[string]any{}
	rows4, err := s.PG.Query(r.Context(), `SELECT id, sample_type_id, sealed, status, current_holder_id, current_lat, current_lon, location_at, target_lab_id, delivery_deadline FROM sample`)
	if err == nil {
		defer rows4.Close()
		staleThreshold := time.Now().Add(-s.Cfg.WorkerStale)
		for rows4.Next() {
			var id, st, sealed, status, holder string
			var lat, lon float64
			var locAt time.Time
			var lab string
			var dl time.Time
			if err := rows4.Scan(&id, &st, &sealed, &status, &holder, &lat, &lon, &locAt, &lab, &dl); err == nil {
				sampleSummaries = append(sampleSummaries, map[string]any{
					"sampleId": id, "sampleTypeId": st, "sealed": sealed, "status": status,
					"currentHolderId": holder,
					"currentLocation": map[string]any{"latitude": lat, "longitude": lon},
					"locationStale": locAt.Before(staleThreshold),
					"locationRecordedAt": locAt,
					"targetLaboratoryId": lab, "deliveryDeadline": dl,
				})
			}
		}
	}

	snap, _ := s.Serv.LastPublished(r.Context())
	out := operationsStateEnvelope{}
	out.Data.Locations = locations
	out.Data.Connections = connections
	out.Data.Workers = workers
	out.Data.SampleSummaries = sampleSummaries
	out.Data.SnapshotVersion = snap.Version
	writeJSON(w, http.StatusOK, out)
}

