package httpapi

import (
	"net/http"

	"github.com/lablogistics/models"
)

// /api/ui/bootstrap returns metadata describing the UI and the live set of
// sample types, locations and laboratories available. This drives the
// dropdowns in the SPA without requiring auth.
func (s *Server) handleUIBootstrap(w http.ResponseWriter, r *http.Request) {
	sampleTypes := []models.SampleType{}
	rows, err := s.PG.Query(r.Context(), `SELECT id, code, name, container_type, temp_min_c, temp_max_c, requires_cooled, requires_qualified, array_to_string(incompatible_with, ','), active FROM sample_type ORDER BY name ASC`)
	if err == nil {
		defer rows.Close()
		for rows.Next() {
			var st models.SampleType
			var incompRaw string
			if err := rows.Scan(&st.ID, &st.Code, &st.Name, &st.ContainerType, &st.TempMinC, &st.TempMaxC, &st.RequiresCooled, &st.RequiresQualified, &incompRaw, &st.Active); err == nil {
				st.IncompatibleWith = splitComma(incompRaw)
				sampleTypes = append(sampleTypes, st)
			}
		}
	}
	locations := []models.Location{}
	rows2, err := s.PG.Query(r.Context(), `SELECT id, name, latitude, longitude, coverage_km, handling_min, active, is_collection_point, is_transfer_point, is_hub, is_laboratory, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units, array_to_string(accepted_sample_types, ',') FROM location ORDER BY name ASC`)
	if err == nil {
		defer rows2.Close()
		for rows2.Next() {
			var l models.Location
			var accepted string
			if err := rows2.Scan(&l.ID, &l.Name, &l.Coordinate.Latitude, &l.Coordinate.Longitude, &l.CoverageKm, &l.HandlingMin, &l.Active, &l.Functions.CollectionPoint, &l.Functions.TransferPoint, &l.Functions.Hub, &l.Functions.Laboratory, &l.Capacity.CapacityUnits, &l.Capacity.ReservedUnits, &l.Capacity.CooledCapacityUnits, &l.Capacity.CooledReservedUnits, &accepted); err == nil {
				l.AcceptedSampleTypes = splitComma(accepted)
				l.Capacity.AvailableUnits = l.Capacity.CapacityUnits - l.Capacity.ReservedUnits
				l.Capacity.CooledAvailableUnits = l.Capacity.CooledCapacityUnits - l.Capacity.CooledReservedUnits
				locations = append(locations, l)
			}
		}
	}
	roles := []string{
		"administrator", "dispatcher", "requester", "collection_professional",
		"delivery_partner", "node_handler", "laboratory_team",
	}
	writeJSON(w, http.StatusOK, map[string]any{
		"data": map[string]any{
			"sampleTypes": sampleTypes,
			"locations":   locations,
			"roles":       roles,
			"defaults": map[string]any{
				"containerType": "sealed_bag",
				"temperature": map[string]any{"minC": 2.0, "maxC": 8.0},
				"coverageKm":   5.0,
			},
			"map": map[string]any{
				"tileUrl": "/tiles/bangalore.pmtiles",
				"styleUrl": "/tiles/style.json",
				"defaultCenter": map[string]any{"latitude": 12.97, "longitude": 77.59},
				"defaultZoom":  11,
			},
		},
	})
}

// /ready returns 200 with {"status":"ready"} only when the app is fully wired.
func (s *Server) handleReady(w http.ResponseWriter, r *http.Request) {
	if !s.PG.Ready(r.Context()) {
		writeJSON(w, http.StatusServiceUnavailable, map[string]any{"status": "unready", "reason": "postgres"})
		return
	}
	if s.RDB != nil && !s.RDB.Ping(r.Context()) {
		writeJSON(w, http.StatusServiceUnavailable, map[string]any{"status": "unready", "reason": "redis"})
		return
	}
	if s.Mongo != nil && !s.Mongo.Ping(r.Context()) {
		writeJSON(w, http.StatusServiceUnavailable, map[string]any{"status": "unready", "reason": "mongo"})
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"status": "ready"})
}

