	// Create default sample types if missing (Amber, Indigo, Frost, Pulse)
	mustDefault(ctx, pg)

	// Create initial admin if no users
	if err := ensureInitialAdmin(ctx, pg, cfg.AdminUsername, cfg.AdminPassword); err != nil {
		log.Printf("ensure admin: %v", err)
	}

	// Build server
	srv := httpapi.New(cfg, pg, mg, rdb)
	httpSrv := &http.Server{
		Addr:    fmt.Sprintf(":%d", cfg.Port),
		Handler: srv.Router(),
		ReadHeaderTimeout: 5 * time.Second,
	}

	// Start static file server for tiles and SPA via chi's Mount
	// (static dir is optional; the SPA build will be served by the same mux via the prefix handler)
	mux := srv.Router()
	go httpSrvServe(httpSrv, mux)

	log.Printf("lablogistics listening on :%d", cfg.Port)

	// Block and trap signals
	stop := make(chan os.Signal, 1)
	signal.Notify(stop, syscall.SIGINT, syscall.SIGTERM)
	<-stop
	log.Printf("shutting down")

	shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	_ = httpSrv.Shutdown(shutdownCtx)
}

func httpSrvServe(s *http.Server, h http.Handler) {
	if err := s.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
