package main

import (
	"context"
	"errors"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/signal"
	"path/filepath"
	"strings"
	"syscall"
	"time"

	"github.com/lablogistics/auth"
	"github.com/lablogistics/config"
	"github.com/lablogistics/httpapi"
	"github.com/lablogistics/service"
	"github.com/lablogistics/store"
)

func main() {
	cfg, err := config.Load()
	if err != nil {
		log.Fatalf("load config: %v", err)
	}
	ctx := context.Background()

	pg, err := store.NewPostgres(ctx, cfg.DatabaseURL)
	if err != nil {
		log.Fatalf("postgres: %v", err)
	}
	defer pg.Close()

	migDir := envOr("MIGRATIONS_DIR", "")
	if migDir == "" {
		migDir = filepath.Join(workingDir(), "internal/store/migrations")
	}
	if err := pg.ApplyMigrations(ctx, migDir); err != nil {
		log.Fatalf("migrate: %v", err)
	}

	var rdb *store.Redis
	if cfg.RedisURL != "" {
		rdb, err = store.NewRedis(ctx, cfg.RedisURL)
		if err != nil {
			log.Printf("redis warn: %v", err)
		}
	}

	var mg *store.Mongo
	if cfg.MongoURI != "" {
		mg, err = store.NewMongo(ctx, cfg.MongoURI, cfg.MongoDB)
		if err != nil {
			log.Printf("mongo warn: %v", err)
		}
	}

	mustDefault(ctx, pg)

	if err := ensureInitialAdmin(ctx, pg, cfg.AdminUsername, cfg.AdminPassword); err != nil {
		log.Printf("ensure admin: %v", err)
	}

	// publish initial serviceability
	svc := service.NewServiceability(pg)
	if _, err := svc.PublishNewSnapshot(ctx); err != nil {
		log.Printf("snapshot warn: %v", err)
	}

	srv := httpapi.New(cfg, pg, mg, rdb)
	httpSrv := &http.Server{
		Addr:              fmt.Sprintf(":%d", cfg.Port),
		Handler:           srv.Router(),
		ReadHeaderTimeout: 5 * time.Second,
	}
	go func() {
		if err := httpSrv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			log.Fatalf("server: %v", err)
		}
	}()

	log.Printf("lablogistics listening on :%d", cfg.Port)

	stop := make(chan os.Signal, 1)
	signal.Notify(stop, syscall.SIGINT, syscall.SIGTERM)
	<-stop
	log.Printf("shutting down")
	shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	_ = httpSrv.Shutdown(shutdownCtx)
}

func envOr(k, def string) string {
	if v := os.Getenv(k); v != "" {
		return v
	}
	return def
}

func workingDir() string {
	dir, _ := os.Getwd()
	for i := 0; i < 6; i++ {
		p := filepath.Join(dir, "internal/store/migrations")
		if _, err := os.Stat(p); err == nil {
			return dir
		}
		dir = filepath.Dir(dir)
	}
	return "."
}

func mustDefault(ctx context.Context, pg *store.Postgres) {
	defaults := []struct {
		Code, Name, Container string
		Min, Max              float64
		Cooled, Qualified     bool
	}{
		{"amber", "Amber", "amber_tube", 2.0, 8.0, false, true},
		{"indigo", "Indigo", "indigo_tube", 2.0, 8.0, false, true},
		{"frost", "Frost", "frost_cooler", -20.0, -10.0, true, true},
		{"pulse", "Pulse", "pulse_vial", 2.0, 8.0, false, true},
	}
	for _, d := range defaults {
		var id string
		_ = pg.QueryRow(ctx, "SELECT id FROM sample_type WHERE code=$1", d.Code).Scan(&id)
		if id == "" {
			newID := "spt_" + strings.ReplaceAll(d.Code, " ", "_") + "_default"
			_, _ = pg.Exec(ctx, `INSERT INTO sample_type (id, code, name, container_type, temp_min_c, temp_max_c, requires_cooled, requires_qualified, incompatible_with, active) VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9,TRUE) ON CONFLICT (id) DO NOTHING`,
				newID, d.Code, d.Name, d.Container, d.Min, d.Max, d.Cooled, d.Qualified, []string{})
		}
	}
}

func ensureInitialAdmin(ctx context.Context, pg *store.Postgres, username, password string) error {
	if username == "" || password == "" {
		return nil
	}
	var cnt int
	if err := pg.QueryRow(ctx, "SELECT COUNT(1) FROM app_user").Scan(&cnt); err != nil {
		return err
	}
	if cnt > 0 {
		return nil
	}
	hash, err := auth.HashPassword(password)
	if err != nil {
		return err
	}
	_, err = pg.Exec(ctx, `INSERT INTO app_user (id, username, password_hash, full_name, roles, active_role, certifications) VALUES ($1,$2,$3,$4,$5,$6,$7) ON CONFLICT (username) DO NOTHING`,
		"usr_admin_initial", username, hash, "Initial Administrator", []string{"administrator"}, "administrator", []string{})
	return err
}

