type Server struct {
	Cfg   config.Config
	PG    *store.Postgres
	Mongo *store.Mongo
	RDB   *store.Redis
	Audit *service.Audit
	Serv  *service.Serviceability
	Hub   *realtime.Hub
	Br    *events.Broker
}

// New constructs the Server.
func New(cfg config.Config, pg *store.Postgres, m *store.Mongo, rdb *store.Redis) *Server {
	br := events.NewBroker()
	if rdb != nil {
		events.SetRedisPublisher(rdb)
	}
	return &Server{
		Cfg:   cfg,
		PG:    pg,
		Mongo: m,
		RDB:   rdb,
		Audit: service.NewAudit(pg, m),
		Serv:  service.NewServiceability(pg),
		Br:    br,
		Hub:   realtime.NewHub(br, rdb),
	}
}

func (s *Server) Router() http.Handler {
	r := chi.NewRouter()
	r.Use(middleware.RequestID)
	r.Use(middleware.RealIP)
	r.Use(middleware.Recoverer)
	r.Use(middleware.Timeout(30 * time.Second))
	r.Use(cors.Handler(cors.Options{
		AllowedOrigins:   []string{"*"},
		AllowedMethods:   []string{"GET", "POST", "PUT", "PATCH", "DELETE", "OPTIONS"},
		AllowedHeaders:   []string{"Accept", "Authorization", "Content-Type", "X-CSRF-Token", "X-Session-Token"},
		ExposedHeaders:   []string{"Link"},
		AllowCredentials: false,
		MaxAge:           300,
	}))

	r.Get("/ready", s.handleReady)

	// Bootstrap serves UI bootstrap before auth
	r.Get("/api/ui/bootstrap", s.handleUIBootstrap)

	// WebSocket for realtime
	r.Get("/api/realtime", s.Hub.HandleWS)

	// Public APIs (auth uses header)
	r.Route("/api", func(r chi.Router) {
		r.Post("/authenticate-user", s.handleAuthenticate)
		// Protected group:
		r.Group(func(r chi.Router) {
			r.Use(s.authMiddleware)
			// Roles:
			// Admin
			r.Post("/create-user", s.requireRoles(models.RoleAdministrator), s.handleCreateUser)
			r.Post("/update-user-access", s.requireRoles(models.RoleAdministrator), s.handleUpdateUserAccess)
			r.Get("/read-user/{userId}", s.handleReadUser)
			r.Post("/read-user", s.handleReadUserByBody)

			// Network admin
			r.Post("/create-location", s.requireRoles(models.RoleAdministrator), s.handleCreateLocation)
			r.Post("/update-location", s.requireRoles(models.RoleAdministrator), s.handleUpdateLocation)
			r.Post("/set-location-status", s.requireRoles(models.RoleAdministrator), s.handleSetLocationStatus)
			r.Post("/set-location-function-status", s.requireRoles(models.RoleAdministrator), s.handleSetLocationFunctionStatus)
			r.Post("/create-connection", s.requireRoles(models.RoleAdministrator), s.handleCreateConnection)
			r.Post("/set-connection-status", s.requireRoles(models.RoleAdministrator), s.handleSetConnectionStatus)
			r.Post("/configure-capacity", s.requireRoles(models.RoleAdministrator, models.RoleNodeHandler, models.RoleLaboratoryTeam), s.handleConfigureCapacity)
			r.Post("/configure-laboratory-acceptance", s.requireRoles(models.RoleAdministrator, models.RoleLaboratoryTeam), s.handleConfigureLaboratoryAcceptance)

			// Sample type admin
			r.Post("/create-sample-type", s.requireRoles(models.RoleAdministrator), s.handleCreateSampleType)
			r.Post("/update-sample-type", s.requireRoles(models.RoleAdministrator), s.handleUpdateSampleType)

			// Serviceability
			r.Post("/read-serviceability-snapshot", s.handleReadServiceabilitySnapshot)

			// Active role + work list
			r.Post("/select-active-role", s.handleSelectActiveRole)
			r.Post("/list-role-work", s.handleListRoleWork)

			// Worker self
			r.Post("/record-worker-location", s.handleRecordWorkerLocation)
			r.Post("/set-worker-availability", s.handleSetWorkerAvailability)

			// Requests and samples
			r.Post("/create-collection-request", s.requireRoles(models.RoleRequester), s.handleCreateCollectionRequest)
			r.Post("/check-serviceability", s.requireRoles(models.RoleRequester), s.handleCheckServiceability)
			r.Post("/collect-and-seal-sample", s.requireRoles(models.RoleCollectionProfessional, models.RoleAdministrator), s.handleCollectAndSealSample)
			r.Post("/ingest-presealed-sample", s.requireRoles(models.RoleCollectionProfessional, models.RoleDeliveryPartner, models.RoleNodeHandler, models.RoleLaboratoryTeam, models.RoleAdministrator), s.handleIngestPresealedSample)

			// Handoff & transport
			r.Post("/initiate-handoff", s.handleInitiateHandoff)
			r.Post("/confirm-handoff", s.handleConfirmHandoff)
			r.Post("/update-assignment-progress", s.handleUpdateAssignmentProgress)
			r.Post("/accept-assignment", s.handleAcceptAssignment)
			r.Post("/decline-assignment", s.handleDeclineAssignment)
			r.Post("/record-handling-checkpoint", s.handleRecordHandlingCheckpoint)

			// Laboratory
			r.Post("/confirm-laboratory-receipt", s.requireRoles(models.RoleLaboratoryTeam, models.RoleAdministrator), s.handleConfirmLaboratoryReceipt)
			r.Post("/record-laboratory-exception", s.requireRoles(models.RoleLaboratoryTeam, models.RoleAdministrator), s.handleRecordLaboratoryException)

			// Disruption + replanning (dispatcher/admin)
			r.Post("/report-disruption", s.requireRoles(models.RoleDispatcher, models.RoleAdministrator), s.handleReportDisruption)
			r.Post("/reroute-journey", s.requireRoles(models.RoleDispatcher, models.RoleAdministrator), s.handleRerouteJourney)
			r.Post("/cancel-journey", s.requireRoles(models.RoleDispatcher, models.RoleAdministrator), s.handleCancelJourney)
			r.Post("/split-journey", s.requireRoles(models.RoleDispatcher, models.RoleAdministrator), s.handleSplitJourney)
			r.Post("/merge-journeys", s.requireRoles(models.RoleDispatcher, models.RoleAdministrator), s.handleMergeJourneys)
			r.Post("/edit-active-plan", s.requireRoles(models.RoleDispatcher, models.RoleAdministrator), s.handleEditActivePlan)

			// Read endpoints
			r.Post("/read-operations-state", s.handleReadOperationsState)
			r.Post("/read-sample-lifecycle", s.handleReadSampleLifecycle)
			r.Get("/read-sample-state/{sampleId}", s.handleReadSampleState)
			r.Post("/read-journey-plan", s.handleReadJourneyPlan)
