		return
	}
	var u models.User
	var rolesRaw, certsRaw string
	var assignedNode, assignedLab string
	if err := s.PG.QueryRow(r.Context(), `SELECT id, username, full_name, array_to_string(roles, ','), active_role, assigned_node, assigned_lab, array_to_string(certifications, ','), available, created_at FROM app_user WHERE id=$1`, id).Scan(&u.ID, &u.Username, &u.FullName, &rolesRaw, &u.ActiveRole, &assignedNode, &assignedLab, &certsRaw, &u.Available, &u.CreatedAt); err != nil {
		writeError(w, http.StatusNotFound, "user_not_found", "user not found")
		return
	}
	out := readUserResp{}
	out.Data.UserID = u.ID
	out.Data.Username = u.Username
	out.Data.FullName = u.FullName
	out.Data.Roles = splitComma(rolesRaw)
	out.Data.ActiveRole = string(u.ActiveRole)
	out.Data.AssignedNodeID = assignedNode
	out.Data.AssignedLabID = assignedLab
	out.Data.Certifications = splitComma(certsRaw)
	out.Data.Available = u.Available
	writeJSON(w, http.StatusOK, out)
}

func splitComma(s string) []string {
	out := []string{}
	for _, p := range strings.Split(s, ",") {
		if p = strings.TrimSpace(p); p != "" {
			out = append(out, p)
		}
	}
	return out
}

