	if req.Username == "" || req.Password == "" || req.FullName == "" {
		writeError(w, http.StatusBadRequest, "invalid_json", "username, password, fullName required")
		return
	}
	if len(req.Roles) == 0 {
		writeError(w, http.StatusBadRequest, "invalid_json", "at least one role required")
