		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	id := "usr_" + randID()
	active := req.Roles[0]
	rolesPG := pgTextArr(req.Roles)
	certsPG := pgTextArr(req.Certifications)
	_, err = s.PG.Exec(r.Context(), `INSERT INTO app_user (id, username, password_hash, full_name, roles, active_role, assigned_node, assigned_lab, certifications) VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)`,
		id, req.Username, hash, req.FullName, rolesPG, active, req.AssignedNodeID, req.AssignedLabID, certsPG)
	if err != nil {
