type recordCheckpointReq struct {
	SampleID         string    `json:"sampleId"`
	ObservedContainer string   `json:"observedContainerType"`
	ObservedTemperature float64 `json:"observedTemperatureC"`
	RecordedAt       time.Time `json:"recordedAt"`
}

func (s *Server) handleRecordHandlingCheckpoint(w http.ResponseWriter, r *http.Request) {
	uid := r.Context().Value(ctxUserID).(string)
	role := r.Context().Value(ctxUserRole).(string)
	var req recordCheckpointReq
	if err := readJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	var containerType string
	var tempMin, tempMax float64
	if err := s.PG.QueryRow(r.Context(), "SELECT container_type, temp_min_c, temp_max_c FROM sample WHERE id=$1", req.SampleID).Scan(&containerType, &tempMin, &tempMax); err != nil {
		writeError(w, http.StatusNotFound, "sample_not_found", "sample not found")
		return
	}
	excp := ""
	if req.ObservedContainer != "" && containerType != "" && req.ObservedContainer != containerType {
		excp = "container_mismatch"
	}
	if req.ObservedTemperature < tempMin || req.ObservedTemperature > tempMax {
		if excp == "" {
			excp = "temperature_out_of_range"
		}
	}
	if excp != "" {
		if _, err := s.PG.Exec(r.Context(), `UPDATE sample SET exception=$1 WHERE id=$2`, excp, req.SampleID); err != nil {
			writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}
	}
	s.Audit.Record(r.Context(), uid, string(role), "record_handling_checkpoint", "sample", req.SampleID, true, req)
	s.Audit.TimelineEvent(r.Context(), req.SampleID, "", "", uid, string(role), "handling_checkpoint", "sample", req.SampleID, true, req)
	writeJSON(w, http.StatusCreated, map[string]any{"data": map[string]any{"sampleId": req.SampleID, "exception": excp}})
}

func serializeAssignment(a models.Assignment) assignmentData {
	return assignmentData{
		AssignmentID: a.ID, JourneyID: a.JourneyID, SampleID: a.SampleID, Kind: a.Kind,
		Sequence: a.Sequence, FromLocationID: a.FromLocationID, ToLocationID: a.ToLocationID,
		WorkerID: a.WorkerID, Status: a.Status, OfferedAt: a.OfferedAt,
		OfferExpiresAt: a.OfferExpiresAt, ResolvesCapacity: a.ResolvesCapacity, UsesCooled: a.UsesCooled,
	}
}

observation.new_content:
package httpapi

import (
	"context"
	"net/http"
	"time"

	"github.com/jackc/pgx/v5"
	"lablogistics/internal/models"
)

// ctx returns a context bound to the server (used by async recomputes).
func (s *Server) ctx() context.Context {
	c, _ := context.WithTimeout(context.Background(), 30*time.Second)
	return c
}

// ----- collect & seal sample --------------------------------------------

type collectAndSealReq struct {
	SampleID         string         `json:"sampleId"`
	CollectionOrigin models.Coordinate `json:"collectionOrigin"`
	ContainerType    string         `json:"containerType"`
	ObservedTempC    float64        `json:"observedTemperatureC"`
	SealedAt         time.Time      `json:"sealedAt"`
}

func (s *Server) handleCollectAndSealSample(w http.ResponseWriter, r *http.Request) {
	uid := r.Context().Value(ctxUserID).(string)
	role := r.Context().Value(ctxUserRole).(string)
	var req collectAndSealReq
	if err := readJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if req.SampleID == "" {
		writeError(w, http.StatusBadRequest, "invalid_json", "sampleId required")
		return
	}

	var sample models.Sample
	var incompRaw string
	if err := s.PG.QueryRow(r.Context(), `SELECT id, requester_id, origin_type, origin_node_id, origin_lat, origin_lon, sample_type_id, container_type, temp_min_c, temp_max_c, array_to_string(incompatible_types, ','), serviceability, sealed, status, current_holder_id, current_lat, current_lon, location_at, target_lab_id, active_journey_id, array_to_string(active_assignments, ','), exception, requested_at, earliest_collection, latest_collection, delivery_deadline FROM sample WHERE id=$1`, req.SampleID).Scan(
		&sample.ID, &sample.RequesterID, &sample.OriginType, &sample.OriginNodeID, &sample.Origin.Latitude, &sample.Origin.Longitude,
		&sample.SampleTypeID, &sample.ContainerType, &sample.TempMinC, &sample.TempMaxC, &incompRaw, &sample.Serviceability, &sample.Sealed, &sample.Status, &sample.CurrentHolderID, &sample.CurrentLocation.Latitude, &sample.CurrentLocation.Longitude,
		&sample.LocationAt, &sample.TargetLabID, &sample.ActiveJourneyID, &activeAssignmentsRaw, &sample.Exception, &sample.RequestedAt, &sample.EarliestCollection, &sample.LatestCollection, &sample.DeliveryDeadline,
	); err != nil {
		if err == pgx.ErrNoRows {
			writeError(w, http.StatusNotFound, "sample_not_found", "sample not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	sample.IncompatibleTypes = splitComma(incompRaw)

	// Check collector qualification (if sample type requires it)
	var requiresQualified bool
	_ = s.PG.QueryRow(r.Context(), "SELECT requires_qualified FROM sample_type WHERE id=$1", sample.SampleTypeID).Scan(&requiresQualified)
	if requiresQualified {
		var certsRaw string
		_ = s.PG.QueryRow(r.Context(), "SELECT array_to_string(certifications, ',') FROM app_user WHERE id=$1", uid).Scan(&certsRaw)
		has := false
		for _, c := range splitComma(certsRaw) {
			if c == sample.SampleTypeID {
				has = true
				break
			}
		}
		if !has {
			writeError(w, http.StatusForbidden, "not_certified", "collector lacks qualification for this sample type")
			return
		}
	}
	// Window check
	now := time.Now().UTC()
	if now.Before(sample.EarliestCollection) || now.After(sample.LatestCollection) {
		writeError(w, http.StatusConflict, "outside_collection_window", "current time outside collection window")
		return
	}

	// Update sample as sealed + held by collector
	if _, err := s.PG.Exec(r.Context(), `UPDATE sample SET sealed=TRUE, status='in_transit', current_holder_id=$1, current_lat=$2, current_lon=$3, location_at=$4, container_type=COALESCE(NULLIF($5,''), container_type), exception=CASE WHEN $6 < temp_min_c OR $6 > temp_max_c THEN 'temperature_out_of_range' ELSE exception END WHERE id=$7`,
		uid, req.CollectionOrigin.Latitude, req.CollectionOrigin.Longitude, req.SealedAt, req.ContainerType, req.ObservedTempC, sample.ID); err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}

	// Find a target laboratory (use first one that accepts the sample type)
	var labID string
	if sample.TargetLabID != "" {
		labID = sample.TargetLabID
	} else {
		_ = s.PG.QueryRow(r.Context(), `SELECT id FROM location WHERE active=TRUE AND is_laboratory=TRUE AND $1 = ANY(accepted_sample_types) LIMIT 1`, sample.SampleTypeID).Scan(&labID)
	}
	if labID == "" {
		writeError(w, http.StatusConflict, "no_laboratory", "no active laboratory accepts this sample type")
		return
	}
	// Find nearest collection point
	var cpID string
	_ = s.PG.QueryRow(r.Context(), `SELECT id FROM location WHERE active=TRUE AND is_collection_point=TRUE ORDER BY ((latitude-$1)*(latitude-$1)+(longitude-$2)*(longitude-$2)) ASC LIMIT 1`, req.CollectionOrigin.Latitude, req.CollectionOrigin.Longitude).Scan(&cpID)
	if cpID == "" {
		writeError(w, http.StatusConflict, "no_collection_point", "no active collection point")
		return
	}

	// Create journey with two legs: home->cp, cp->lab
	journeyID := "jrn_" + randID()
	tx, err := s.PG.Begin(r.Context())
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	defer tx.Rollback(r.Context())
	if _, err := tx.Exec(r.Context(), `INSERT INTO journey (id, plan_version, route_mode, status, estimated_delivery, total_cost, capacity_used, capacity_available, sample_ids, valid) VALUES ($1,1,'multi_stop','active',$2,0,1,1,$3,TRUE)`,
		journeyID, sample.DeliveryDeadline, []string{sample.ID}); err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if _, err := tx.Exec(r.Context(), `INSERT INTO journey_stop (id, journey_id, location_id, stop_type, sequence, estimated_at, dwell_min) VALUES ($1,$2,'','pickup',0,$3,0)`,
		"stp_"+randID(), journeyID, now); err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if _, err := tx.Exec(r.Context(), `INSERT INTO journey_stop (id, journey_id, location_id, stop_type, sequence, estimated_at, dwell_min) VALUES ($1,$2,$3,'handoff',1,$4,0)`,
		"stp_"+randID(), journeyID, cpID, now); err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if _, err := tx.Exec(r.Context(), `INSERT INTO journey_stop (id, journey_id, location_id, stop_type, sequence, estimated_at, dwell_min) VALUES ($1,$2,$3,'delivery',2,$4,0)`,
		"stp_"+randID(), journeyID, labID, sample.DeliveryDeadline); err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}

	// First transport leg from origin to cp: assign the collector themselves
	assignID := "asn_" + randID()
	if _, err := tx.Exec(r.Context(), `INSERT INTO assignment (id, journey_id, sample_id, kind, sequence, from_location_id, to_location_id, worker_id, status, offer_expires_at, offered_at, resolves_capacity, uses_cooled) VALUES ($1,$2,$3,'transport',1,'',$4,$5,'accepted',$6,$6,TRUE,FALSE)`,
		assignID, journeyID, sample.ID, cpID, uid, now); err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if _, err := tx.Exec(r.Context(), `UPDATE sample SET active_journey_id=$1, active_assignments=ARRAY[$2]::text[] WHERE id=$3`, journeyID, assignID, sample.ID); err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if err := tx.Commit(r.Context()); err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}

	s.Audit.Record(r.Context(), uid, string(role), "collect_and_seal_sample", "sample", sample.ID, true, req)
	s.Audit.TimelineEvent(r.Context(), sample.ID, journeyID, assignID, uid, string(role), "collected_and_sealed", "sample", sample.ID, true, req)
	s.Br.Publish("sample.sealed", "sample", sample.ID, map[string]any{"journeyId": journeyID, "assignmentId": assignID, "holderId": uid})

	writeJSON(w, http.StatusCreated, map[string]any{"data": map[string]any{"sampleId": sample.ID, "journeyId": journeyID, "assignmentId": assignID, "currentHolderId": uid, "status": "sealed"}})
}

type ingestPresealedReq struct {
	SampleTypeID        string            `json:"sampleTypeId"`
	OriginNodeID        string            `json:"originNodeId"`
	ContainerType       string            `json:"containerType"`
	ObservedTemperature float64           `json:"observedTemperatureC"`
	SealedAt            time.Time         `json:"sealedAt"`
	EarliestCollection  time.Time         `json:"earliestCollectionAt"`
	LatestCollection    time.Time         `json:"latestCollectionAt"`
	DeliveryDeadline    time.Time         `json:"deliveryDeadline"`
	TargetLaboratoryID  string            `json:"targetLaboratoryId"`
}

func (s *Server) handleIngestPresealedSample(w http.ResponseWriter, r *http.Request) {
	uid := r.Context().Value(ctxUserID).(string)
	role := r.Context().Value(ctxUserRole).(string)
	var req ingestPresealedReq
	if err := readJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if req.SampleTypeID == "" || req.OriginNodeID == "" || req.TargetLaboratoryID == "" {
		writeError(w, http.StatusBadRequest, "invalid_json", "sampleTypeId, originNodeId, targetLaboratoryId required")
		return
	}
	var st models.SampleType
	var incompRaw string
	if err := s.PG.QueryRow(r.Context(), `SELECT id, code, name, container_type, temp_min_c, temp_max_c, requires_cooled, requires_qualified, array_to_string(incompatible_with, ','), active FROM sample_type WHERE id=$1`, req.SampleTypeID).Scan(&st.ID, &st.Code, &st.Name, &st.ContainerType, &st.TempMinC, &st.TempMaxC, &st.RequiresCooled, &st.RequiresQualified, &incompRaw, &st.Active); err != nil {
		writeError(w, http.StatusNotFound, "sample_type_not_found", "sample type not found")
		return
	}
	st.IncompatibleWith = splitComma(incompRaw)
	// verify origin node is a clinic or network node (not home)
	var isClinic bool
	_ = s.PG.QueryRow(r.Context(), "SELECT is_transfer_point OR is_hub OR is_laboratory FROM location WHERE id=$1", req.OriginNodeID).Scan(&isClinic)
	if !isClinic {
		writeError(w, http.StatusConflict, "origin_not_clinic_or_node", "pre-sealed sample origin must be a clinic or network node")
		return
	}
	// Lookup lab coordinates
	var labLat, labLon float64
	if err := s.PG.QueryRow(r.Context(), "SELECT latitude, longitude FROM location WHERE id=$1", req.TargetLaboratoryID).Scan(&labLat, &labLon); err != nil {
		writeError(w, http.StatusNotFound, "laboratory_not_found", "laboratory not found")
		return
	}
	var nodeLat, nodeLon float64
	if err := s.PG.QueryRow(r.Context(), "SELECT latitude, longitude FROM location WHERE id=$1", req.OriginNodeID).Scan(&nodeLat, &nodeLon); err != nil {
		writeError(w, http.StatusNotFound, "origin_not_found", "origin node not found")
		return
	}
	// Determine holder role allows holding: collector/delivery_partner/node/lab are allowed
	allowed := map[string]bool{"collection_professional": true, "delivery_partner": true, "node_handler": true, "laboratory_team": true, "administrator": true}
	if !allowed[string(role)] {
		writeError(w, http.StatusForbidden, "insufficient_role", "role cannot hold a sealed sample")
		return
	}

	reqID := "req_" + randID()
	sampleID := "smp_" + randID()
	journeyID := "jrn_" + randID()
	assignID := "asn_" + randID()
	now := time.Now().UTC()

	tx, err := s.PG.Begin(r.Context())
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	defer tx.Rollback(r.Context())
	if _, err := tx.Exec(r.Context(), `INSERT INTO request (id, requester_id, origin_type, origin_node_id, origin_lat, origin_lon, sample_type_id, earliest_collection, latest_collection, delivery_deadline, target_lab_id, status, created_at) VALUES ($1,$2,'node',$3,$4,$5,$6,$7,$8,$9,$10,'open',$11)`,
		reqID, uid, req.OriginNodeID, nodeLat, nodeLon, st.ID, req.EarliestCollection, req.LatestCollection, req.DeliveryDeadline, req.TargetLaboratoryID, now); err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	container := req.ContainerType
	if container == "" {
		container = st.ContainerType
	}
	if _, err := tx.Exec(r.Context(), `INSERT INTO sample (id, request_id, requester_id, origin_type, origin_node_id, origin_lat, origin_lon, sample_type_id, container_type, temp_min_c, temp_max_c, incompatible_types, serviceability, requested_at, earliest_collection, latest_collection, delivery_deadline, sealed, status, current_holder_id, current_lat, current_lon, location_at, target_lab_id, active_journey_id, active_assignments, exception) VALUES ($1,$2,$3,'node',$4,$5,$6,$7,$8,$9,$10,$11,'serviceable',$12,$13,$14,$15,TRUE,'in_transit',$16,$17,$18,$19,$20,$21,ARRAY[$22]::text[], CASE WHEN $23 < temp_min_c OR $23 > temp_max_c THEN 'temperature_out_of_range' ELSE '' END)`,
		sampleID, reqID, uid, req.OriginNodeID, nodeLat, nodeLon, st.ID, container, st.TempMinC, st.TempMaxC,
		pgTextArr(st.IncompatibleWith), now, req.EarliestCollection, req.LatestCollection, req.DeliveryDeadline,
		uid, nodeLat, nodeLon, now, req.TargetLaboratoryID, journeyID, assignID, req.ObservedTemperature); err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if _, err := tx.Exec(r.Context(), `INSERT INTO journey (id, plan_version, route_mode, status, estimated_delivery, total_cost, capacity_used, capacity_available, sample_ids, valid) VALUES ($1,1,'direct','active',$2,0,1,1,$3,TRUE)`,
		journeyID, req.DeliveryDeadline, []string{sampleID}); err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if _, err := tx.Exec(r.Context(), `INSERT INTO journey_stop (id, journey_id, location_id, stop_type, sequence, estimated_at, dwell_min) VALUES ('stp_'||$1,$2,$3,'pickup',0,$4,0)`, randID(), journeyID, req.OriginNodeID, now); err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if _, err := tx.Exec(r.Context(), `INSERT INTO journey_stop (id, journey_id, location_id, stop_type, sequence, estimated_at, dwell_min) VALUES ('stp_'||$1,$2,$3,'delivery',1,$4,0)`, randID(), journeyID, req.TargetLaboratoryID, req.DeliveryDeadline); err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if _, err := tx.Exec(r.Context(), `INSERT INTO assignment (id, journey_id, sample_id, kind, sequence, from_location_id, to_location_id, worker_id, status, offer_expires_at, offered_at, resolves_capacity, uses_cooled) VALUES ($1,$2,$3,'transport',1,$4,$5,$6,'accepted',$7,$7,TRUE,FALSE)`,
		assignID, journeyID, sampleID, req.OriginNodeID, req.TargetLaboratoryID, uid, now); err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if err := tx.Commit(r.Context()); err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	s.Audit.Record(r.Context(), uid, string(role), "ingest_presealed_sample", "sample", sampleID, true, req)
	s.Audit.TimelineEvent(r.Context(), sampleID, journeyID, assignID, uid, string(role), "ingested_presealed", "sample", sampleID, true, req)
	s.Br.Publish("sample.ingested", "sample", sampleID, map[string]any{"journeyId": journeyID, "assignmentId": assignID, "holderId": uid})
	writeJSON(w, http.StatusCreated, map[string]any{"data": map[string]any{"sampleId": sampleID, "journeyId": journeyID, "assignmentId": assignID, "currentHolderId": uid, "status": "in_transit"}})
}

// ----- assignments -------------------------------------------------------

type assignmentEnvelope struct {
	Data assignmentData `json:"data"`
}

type assignmentData struct {
	AssignmentID      string    `json:"assignmentId"`
	JourneyID         string    `json:"journeyId"`
	SampleID          string    `json:"sampleId"`
	Kind              string    `json:"kind"`
	Sequence          int       `json:"sequence"`
	FromLocationID    string    `json:"fromLocationId"`
	ToLocationID      string    `json:"toLocationId"`
	WorkerID          string    `json:"workerId"`
	NodeID            string    `json:"nodeId,omitempty"`
	LaboratoryID      string    `json:"laboratoryId,omitempty"`
	Status            string    `json:"status"`
	OfferedAt         time.Time `json:"offeredAt"`
	OfferExpiresAt    time.Time `json:"offerExpiresAt"`
	ResolvesCapacity  bool      `json:"resolvesCapacity"`
	UsesCooled        bool      `json:"usesCooled"`
}

type acceptAssignmentReq struct {
	AssignmentID string `json:"assignmentId"`
	PlanVersion  int    `json:"planVersion"`
}

func (s *Server) handleAcceptAssignment(w http.ResponseWriter, r *http.Request) {
	uid := r.Context().Value(ctxUserID).(string)
	role := r.Context().Value(ctxUserRole).(string)
	var req acceptAssignmentReq
	if err := readJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if req.AssignmentID == "" {
		writeError(w, http.StatusBadRequest, "invalid_json", "assignmentId required")
		return
	}
	var a models.Assignment
	if err := s.PG.QueryRow(r.Context(), `SELECT id, journey_id, sample_id, kind, sequence, from_location_id, to_location_id, worker_id, status, offer_expires_at, offered_at, resolves_capacity, uses_cooled FROM assignment WHERE id=$1`, req.AssignmentID).Scan(&a.ID, &a.JourneyID, &a.SampleID, &a.Kind, &a.Sequence, &a.FromLocationID, &a.ToLocationID, &a.WorkerID, &a.Status, &a.OfferExpiresAt, &a.OfferedAt, &a.ResolvesCapacity, &a.UsesCooled); err != nil {
		writeError(w, http.StatusNotFound, "assignment_not_found", "assignment not found")
		return
	}
	if a.WorkerID != "" && a.WorkerID != uid {
		writeError(w, http.StatusForbidden, "not_assigned_worker", "this assignment is offered to another worker")
		return
	}
	if a.Status != "offered" {
		writeError(w, http.StatusConflict, "assignment_state", "assignment not offered")
		return
	}
	if time.Now().After(a.OfferExpiresAt) {
		writeError(w, http.StatusConflict, "offer_expired", "offer has expired")
		return
	}
	// Plan version check
	var jPV int
	if err := s.PG.QueryRow(r.Context(), "SELECT plan_version FROM journey WHERE id=$1", a.JourneyID).Scan(&jPV); err != nil {
		writeError(w, http.StatusNotFound, "journey_not_found", "journey not found")
		return
	}
	if req.PlanVersion != 0 && req.PlanVersion != jPV {
		writeError(w, http.StatusConflict, "state_snapshot_changed", "plan version is stale")
		return
	}
	if _, err := s.PG.Exec(r.Context(), `UPDATE assignment SET status='accepted', worker_id=$1, started_at=NOW() WHERE id=$2`, uid, req.AssignmentID); err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	_, _ = s.PG.Exec(r.Context(), `UPDATE sample SET current_holder_id=$1, active_assignments=ARRAY[$2]::text[] WHERE id=$3`, uid, req.AssignmentID, a.SampleID)
	s.Audit.Record(r.Context(), uid, string(role), "accept_assignment", "assignment", req.AssignmentID, true, req)
	s.Audit.TimelineEvent(r.Context(), a.SampleID, a.JourneyID, req.AssignmentID, uid, string(role), "assignment_accepted", "assignment", req.AssignmentID, true, nil)
	s.Br.Publish("assignment.accepted", "assignment", req.AssignmentID, map[string]any{"sampleId": a.SampleID, "workerId": uid})

	a.Status = "accepted"
	a.WorkerID = uid
	writeJSON(w, http.StatusCreated, map[string]any{"data": serializeAssignment(a)})
}

type declineAssignmentReq struct {
	AssignmentID string `json:"assignmentId"`
	PlanVersion  int    `json:"planVersion"`
	Reason       string `json:"reason"`
}

func (s *Server) handleDeclineAssignment(w http.ResponseWriter, r *http.Request) {
	uid := r.Context().Value(ctxUserID).(string)
	role := r.Context().Value(ctxUserRole).(string)
	var req declineAssignmentReq
	if err := readJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	var a models.Assignment
	if err := s.PG.QueryRow(r.Context(), `SELECT id, journey_id, sample_id, kind, sequence, from_location_id, to_location_id, worker_id, status, offer_expires_at, offered_at, resolves_capacity, uses_cooled FROM assignment WHERE id=$1`, req.AssignmentID).Scan(&a.ID, &a.JourneyID, &a.SampleID, &a.Kind, &a.Sequence, &a.FromLocationID, &a.ToLocationID, &a.WorkerID, &a.Status, &a.OfferExpiresAt, &a.OfferedAt, &a.ResolvesCapacity, &a.UsesCooled); err != nil {
		writeError(w, http.StatusNotFound, "assignment_not_found", "assignment not found")
		return
	}
	if a.WorkerID != "" && a.WorkerID != uid {
		writeError(w, http.StatusForbidden, "not_assigned_worker", "this assignment is offered to another worker")
		return
	}
	if _, err := s.PG.Exec(r.Context(), `UPDATE assignment SET status='declined', completed_at=NOW() WHERE id=$1`, req.AssignmentID); err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	s.Audit.Record(r.Context(), uid, string(role), "decline_assignment", "assignment", req.AssignmentID, true, req)
	s.Audit.TimelineEvent(r.Context(), a.SampleID, a.JourneyID, req.AssignmentID, uid, string(role), "assignment_declined", "assignment", req.AssignmentID, true, req)
	s.Br.Publish("assignment.declined", "assignment", req.AssignmentID, map[string]any{"sampleId": a.SampleID, "workerId": uid})
	writeJSON(w, http.StatusCreated, map[string]any{"data": map[string]any{"assignmentId": req.AssignmentID, "status": "declined"}})
}

type updateAssignmentProgressReq struct {
	AssignmentID    string    `json:"assignmentId"`
	ProgressPercent int       `json:"progressPercent"`
	Note            string    `json:"note"`
	Location        models.Coordinate `json:"location"`
	RecordedAt      time.Time `json:"recordedAt"`
}

func (s *Server) handleUpdateAssignmentProgress(w http.ResponseWriter, r *http.Request) {
	uid := r.Context().Value(ctxUserID).(string)
	role := r.Context().Value(ctxUserRole).(string)
	var req updateAssignmentProgressReq
	if err := readJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	var a models.Assignment
	if err := s.PG.QueryRow(r.Context(), `SELECT id, sample_id, worker_id, status FROM assignment WHERE id=$1`, req.AssignmentID).Scan(&a.ID, &a.SampleID, &a.WorkerID, &a.Status); err != nil {
		writeError(w, http.StatusNotFound, "assignment_not_found", "assignment not found")
		return
	}
	if a.WorkerID != uid {
		writeError(w, http.StatusForbidden, "not_assigned_worker", "this assignment belongs to another worker")
		return
	}
	if req.Location.Latitude != 0 || req.Location.Longitude != 0 {
		if _, err := s.PG.Exec(r.Context(), `UPDATE sample SET current_lat=$1, current_lon=$2, location_at=COALESCE(NULLIF($3,'0001-01-01 00:00:00+00:00'::timestamptz), NOW()) WHERE id=$4`, req.Location.Latitude, req.Location.Longitude, req.RecordedAt, a.SampleID); err != nil {
			writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}
	}
	s.Audit.Record(r.Context(), uid, string(role), "update_assignment_progress", "assignment", req.AssignmentID, true, req)
	s.Audit.TimelineEvent(r.Context(), a.SampleID, "", req.AssignmentID, uid, string(role), "assignment_progress", "assignment", req.AssignmentID, true, req)
	s.Br.Publish("assignment.progress", "assignment", req.AssignmentID, map[string]any{"sampleId": a.SampleID, "progress": req.ProgressPercent})
	writeJSON(w, http.StatusCreated, map[string]any{"data": map[string]any{"assignmentId": req.AssignmentID, "progressPercent": req.ProgressPercent}})
}

// ----- handoffs ---------------------------------------------------------

type initiateHandoffReq struct {
	SampleID     string    `json:"sampleId"`
	AssignmentID string    `json:"assignmentId"`
	ReceiverID   string    `json:"receiverId"`
	Location     models.Coordinate `json:"location"`
}

func (s *Server) handleInitiateHandoff(w http.ResponseWriter, r *http.Request) {
	uid := r.Context().Value(ctxUserID).(string)
	role := r.Context().Value(ctxUserRole).(string)
	var req initiateHandoffReq
	if err := readJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	// Verify sender is current holder
	var holder string
	if err := s.PG.QueryRow(r.Context(), "SELECT current_holder_id FROM sample WHERE id=$1", req.SampleID).Scan(&holder); err != nil {
		writeError(w, http.StatusNotFound, "sample_not_found", "sample not found")
		return
	}
	if holder != uid {
		writeError(w, http.StatusForbidden, "not_holder", "sender must be current holder")
		return
	}
	id := "hnd_" + randID()
	now := time.Now().UTC()
	if _, err := s.PG.Exec(r.Context(), `INSERT INTO handoff (id, sample_id, assignment_id, from_user_id, to_user_id, status, initiated_at) VALUES ($1,$2,$3,$4,$5,'initiated',$6)`,
		id, req.SampleID, req.AssignmentID, uid, req.ReceiverID, now); err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	s.Audit.Record(r.Context(), uid, string(role), "initiate_handoff", "handoff", id, true, req)
	s.Audit.TimelineEvent(r.Context(), req.SampleID, "", req.AssignmentID, uid, string(role), "handoff_initiated", "handoff", id, true, req)
	s.Br.Publish("handoff.initiated", "handoff", id, map[string]any{"sampleId": req.SampleID, "from": uid, "to": req.ReceiverID})
	writeJSON(w, http.StatusCreated, map[string]any{"data": map[string]any{"handoffId": id, "status": "initiated"}})
}

type confirmHandoffReq struct {
	HandoffID string    `json:"handoffId"`
	ConfirmedAt time.Time `json:"confirmedAt"`
}

func (s *Server) handleConfirmHandoff(w http.ResponseWriter, r *http.Request) {
	uid := r.Context().Value(ctxUserID).(string)
	role := r.Context().Value(ctxUserRole).(string)
	var req confirmHandoffReq
	if err := readJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	var sampleID, fromUID, toUID, status, assignmentID string
	if err := s.PG.QueryRow(r.Context(), `SELECT sample_id, from_user_id, to_user_id, status, COALESCE(assignment_id,'') FROM handoff WHERE id=$1`, req.HandoffID).Scan(&sampleID, &fromUID, &toUID, &status, &assignmentID); err != nil {
		writeError(w, http.StatusNotFound, "handoff_not_found", "handoff not found")
		return
	}
	if uid != toUID && uid != fromUID {
		writeError(w, http.StatusForbidden, "not_party", "user is not a party to this handoff")
		return
	}
	if status == "completed" {
		writeError(w, http.StatusConflict, "already_completed", "handoff already completed")
		return
	}
	if _, err := s.PG.Exec(r.Context(), `UPDATE handoff SET status='completed', confirmed_at=$1 WHERE id=$2`, req.ConfirmedAt, req.HandoffID); err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	// transfer custody to receiver if not already transferred
	if _, err := s.PG.Exec(r.Context(), `UPDATE sample SET current_holder_id=$1 WHERE id=$2 AND current_holder_id=$3`, toUID, sampleID, fromUID); err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	// Mark prior assignment complete
	if assignmentID != "" {
		_, _ = s.PG.Exec(r.Context(), `UPDATE assignment SET status='completed', completed_at=$1 WHERE id=$2`, req.ConfirmedAt, assignmentID)
	}
	s.Audit.Record(r.Context(), uid, string(role), "confirm_handoff", "handoff", req.HandoffID, true, req)
	s.Audit.TimelineEvent(r.Context(), sampleID, "", assignmentID, uid, string(role), "handoff_completed", "handoff", req.HandoffID, true, req)
	s.Br.Publish("handoff.completed", "handoff", req.HandoffID, map[string]any{"sampleId": sampleID, "holderId": toUID})
	writeJSON(w, http.StatusCreated, map[string]any{"data": map[string]any{"handoffId": req.HandoffID, "status": "completed", "currentHolderId": toUID}})
}

// ----- record handling checkpoint ---------------------------------------

type recordCheckpointReq struct {
	SampleID         string    `json:"sampleId"`
	ObservedContainer string   `json:"observedContainerType"`
	ObservedTemperature float64 `json:"observedTemperatureC"`
	RecordedAt       time.Time `json:"recordedAt"`
}

func (s *Server) handleRecordHandlingCheckpoint(w http.ResponseWriter, r *http.Request) {
	uid := r.Context().Value(ctxUserID).(string)
	role := r.Context().Value(ctxUserRole).(string)
	var req recordCheckpointReq
	if err := readJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	var containerType string
	var tempMin, tempMax float64
	if err := s.PG.QueryRow(r.Context(), "SELECT container_type, temp_min_c, temp_max_c FROM sample WHERE id=$1", req.SampleID).Scan(&containerType, &tempMin, &tempMax); err != nil {
		writeError(w, http.StatusNotFound, "sample_not_found", "sample not found")
		return
	}
	excp := ""
	if req.ObservedContainer != "" && containerType != "" && req.ObservedContainer != containerType {
		excp = "container_mismatch"
	}
	if req.ObservedTemperature < tempMin || req.ObservedTemperature > tempMax {
		if excp == "" {
			excp = "temperature_out_of_range"
		}
	}
	if excp != "" {
		if _, err := s.PG.Exec(r.Context(), `UPDATE sample SET exception=$1 WHERE id=$2`, excp, req.SampleID); err != nil {
			writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}
	}
	s.Audit.Record(r.Context(), uid, string(role), "record_handling_checkpoint", "sample", req.SampleID, true, req)
	s.Audit.TimelineEvent(r.Context(), req.SampleID, "", "", uid, string(role), "handling_checkpoint", "sample", req.SampleID, true, req)
	writeJSON(w, http.StatusCreated, map[string]any{"data": map[string]any{"sampleId": req.SampleID, "exception": excp}})
}

func serializeAssignment(a models.Assignment) assignmentData {
	return assignmentData{
		AssignmentID: a.ID, JourneyID: a.JourneyID, SampleID: a.SampleID, Kind: a.Kind,
		Sequence: a.Sequence, FromLocationID: a.FromLocationID, ToLocationID: a.ToLocationID,
		WorkerID: a.WorkerID, Status: a.Status, OfferedAt: a.OfferedAt,
		OfferExpiresAt: a.OfferExpiresAt, ResolvesCapacity: a.ResolvesCapacity, UsesCooled: a.UsesCooled,
	}
}

