	out.Data.Name = loc.Name
	out.Data.Coordinate = loc.Coordinate
	out.Data.CoverageKm = loc.CoverageKm
	out.Data.HandlingMinutes = loc.HandlingMin
	out.Data.Active = loc.Active
	out.Data.Functions = loc.Functions
	out.Data.Capacity = loc.Capacity
	out.Data.AcceptedSampleTypeIDs = loc.AcceptedSampleTypes
	writeJSON(w, http.StatusCreated, out)
