func (s *Server) handleCreateConnection(w http.ResponseWriter, r *http.Request) {
	var req createConnectionReq
	if err := readJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if req.FromLocationID == "" || req.ToLocationID == "" {
		writeError(w, http.StatusBadRequest, "invalid_json", "from/to required")
		return
	}
	if req.FromLocationID == req.ToLocationID {
		writeError(w, http.StatusBadRequest, "invalid_json", "from and to cannot match")
		return
	}
	id := "con_" + randID()
	_, err := s.PG.Exec(r.Context(), `INSERT INTO connection (id, from_loc, to_loc, travel_min, cost_units, cooled, active, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units) VALUES ($1,$2,$3,$4,$5,$6,TRUE,$7,0,$8,0)`,
		id, req.FromLocationID, req.ToLocationID, req.TravelMinutes, req.CostUnits, req.Cooled, req.CapacityUnits, req.CooledCapacityUnits)
	if err != nil {
		if isFKViolation(err) {
			writeError(w, http.StatusConflict, "unknown_location", "from/to location does not exist")
			return
		}
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
