	out.Data.FromLocationID = req.FromLocationID
	out.Data.ToLocationID = req.ToLocationID
	out.Data.TravelMinutes = req.TravelMinutes
	out.Data.CostUnits = req.CostUnits
	out.Data.Cooled = req.Cooled
	out.Data.Active = true
	out.Data.Capacity = models.Capacity{
