// /api/ui/bootstrap returns metadata describing the UI and the live set of
// sample types, locations and laboratories available. This drives the
// dropdowns in the SPA without requiring auth.
func (s *Server) handleUIBootstrap(w http.ResponseWriter, r *http.Request) {
	sampleTypes := []models.SampleType{}
	rows, err := s.PG.Query(r.Context(), `SELECT id, code, name, container_type, temp_min_c, temp_max_c, requires_cooled, requires_qualified, array_to_string(incompatible_with, ','), active FROM sample_type ORDER BY name ASC`)
	if err == nil {
