package httpapi

import (
	"net/http"
	"time"

	"lablogistics/internal/models"
)

// ----- worker self ------------------------------------------------------

type recordWorkerLocationReq struct {
	Coordinate models.Coordinate `json:"coordinate"`
	RecordedAt time.Time         `json:"recordedAt"`
}

func (s *Server) handleRecordWorkerLocation(w http.ResponseWriter, r *http.Request) {
	uid := r.Context().Value(ctxUserID).(string)
	role := r.Context().Value(ctxUserRole).(string)
	var req recordWorkerLocationReq
	if err := readJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if _, err := s.PG.Exec(r.Context(), `UPDATE app_user SET available=TRUE WHERE id=$1`, uid); err != nil {
		// ignore — this just keeps user available; location stored on samples they hold
	}
	s.Audit.Record(r.Context(), uid, string(role), "record_worker_location", "user", uid, true, req)
	// If user holds samples, update their position
	now := req.RecordedAt
	if now.IsZero() {
		now = time.Now().UTC()
	}
	_, _ = s.PG.Exec(r.Context(), `UPDATE sample SET current_lat=$1, current_lon=$2, location_at=$3 WHERE current_holder_id=$4`, req.Coordinate.Latitude, req.Coordinate.Longitude, now, uid)
	s.Br.Publish("worker.location", "user", uid, map[string]any{"coordinate": req.Coordinate, "recordedAt": now})
	writeJSON(w, http.StatusCreated, map[string]any{"data": map[string]any{"userId": uid, "coordinate": req.Coordinate, "recordedAt": now}})
}

type setWorkerAvailabilityReq struct {
	Available bool `json:"available"`
}

func (s *Server) handleSetWorkerAvailability(w http.ResponseWriter, r *http.Request) {
	uid := r.Context().Value(ctxUserID).(string)
	role := r.Context().Value(ctxUserRole).(string)
	var req setWorkerAvailabilityReq
	if err := readJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if _, err := s.PG.Exec(r.Context(), `UPDATE app_user SET available=$1 WHERE id=$2`, req.Available, uid); err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	s.Audit.Record(r.Context(), uid, string(role), "set_worker_availability", "user", uid, true, req)
	writeJSON(w, http.StatusOK, map[string]any{"data": map[string]any{"userId": uid, "available": req.Available}})
}

// ----- list role work ---------------------------------------------------

type listRoleWorkReq struct {
	ActiveRole string `json:"activeRole"`
	IncludeCompleted bool `json:"includeCompleted"`
}

type listRoleWorkEnvelope struct {
	Data listRoleWorkData `json:"data"`
}

type listRoleWorkData struct {
	Role  string                `json:"role"`
	Items []map[string]any      `json:"items"`
}

func (s *Server) handleListRoleWork(w http.ResponseWriter, r *http.Request) {
	uid := r.Context().Value(ctxUserID).(string)
	role := string(r.Context().Value(ctxUserRole).(models.Role))
	var req listRoleWorkReq
	_ = readJSON(r, &req)
	if req.ActiveRole == "" {
		req.ActiveRole = role
	}
	items := []map[string]any{}

	switch models.Role(req.ActiveRole) {
	case models.RoleRequester:
		rows, err := s.PG.Query(r.Context(), `SELECT id, request_id, sample_type_id, sealed, status, current_holder_id, delivery_deadline FROM sample WHERE requester_id=$1 ORDER BY requested_at DESC`, uid)
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var id, rid, st string
				var sealed, status, holder string
				var dl time.Time
				if err := rows.Scan(&id, &rid, &st, &sealed, &status, &holder, &dl); err == nil {
					items = append(items, map[string]any{"sampleId": id, "requestId": rid, "sampleTypeId": st, "sealed": sealed, "status": status, "currentHolderId": holder, "deliveryDeadline": dl})
				}
			}
		}
	case models.RoleCollectionProfessional, models.RoleDeliveryPartner, models.RoleNodeHandler, models.RoleLaboratoryTeam:
		// Show assignments where the worker is or could be the actor (their node/lab assignments also included)
		var assignedNode, assignedLab string
		_ = s.PG.QueryRow(r.Context(), `SELECT assigned_node, assigned_lab FROM app_user WHERE id=$1`, uid).Scan(&assignedNode, &assignedLab)
		// active assignments held
		rows, err := s.PG.Query(r.Context(), `SELECT id, journey_id, sample_id, kind, from_location_id, to_location_id, status, offer_expires_at FROM assignment WHERE (worker_id=$1 OR (worker_id='' AND status='offered' AND ($2<>'' OR $3<>''))) ORDER BY offered_at DESC LIMIT 50`, uid, assignedNode, assignedLab)
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var a models.Assignment
				if err := rows.Scan(&a.ID, &a.JourneyID, &a.SampleID, &a.Kind, &a.FromLocationID, &a.ToLocationID, &a.Status, &a.OfferExpiresAt); err == nil {
					items = append(items, map[string]any{"assignmentId": a.ID, "journeyId": a.JourneyID, "sampleId": a.SampleID, "kind": a.Kind, "fromLocationId": a.FromLocationID, "toLocationId": a.ToLocationID, "status": a.Status, "offerExpiresAt": a.OfferExpiresAt})
				}
			}
		}
		// samples currently held
		rows2, err := s.PG.Query(r.Context(), `SELECT id, sample_type_id, sealed, status, target_lab_id, delivery_deadline FROM sample WHERE current_holder_id=$1`, uid)
		if err == nil {
			defer rows2.Close()
			for rows2.Next() {
				var id, st string
				var sealed, status, lab string
				var dl time.Time
				if err := rows2.Scan(&id, &st, &sealed, &status, &lab, &dl); err == nil {
					items = append(items, map[string]any{"sampleId": id, "sampleTypeId": st, "sealed": sealed, "status": status, "targetLaboratoryId": lab, "deliveryDeadline": dl})
				}
			}
		}
	case models.RoleDispatcher, models.RoleAdministrator:
		rows, err := s.PG.Query(r.Context(), `SELECT id, sample_type_id, sealed, status, delivery_deadline FROM sample WHERE status NOT IN ('received','cancelled') ORDER BY requested_at DESC LIMIT 100`)
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var id, st string
				var sealed, status string
				var dl time.Time
				if err := rows.Scan(&id, &st, &sealed, &status, &dl); err == nil {
					items = append(items, map[string]any{"sampleId": id, "sampleTypeId": st, "sealed": sealed, "status": status, "deliveryDeadline": dl})
				}
			}
		}
	}
	out := listRoleWorkEnvelope{}
	out.Data.Role = req.ActiveRole
	out.Data.Items = items
	writeJSON(w, http.StatusOK, out)
}

// ----- laboratory receipt / exception -----------------------------------

type confirmLabReceiptReq struct {
	SampleID     string    `json:"sampleId"`
	AssignmentID string    `json:"assignmentId"`
	ReceivedAt   time.Time `json:"receivedAt"`
	Note         string    `json:"note"`
}

func (s *Server) handleConfirmLaboratoryReceipt(w http.ResponseWriter, r *http.Request) {
	uid := r.Context().Value(ctxUserID).(string)
	role := r.Context().Value(ctxUserRole).(string)
	var req confirmLabReceiptReq
	if err := readJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	var labID, sampleTypeID, status string
	if err := s.PG.QueryRow(r.Context(), `SELECT target_lab_id, sample_type_id, status FROM sample WHERE id=$1`, req.SampleID).Scan(&labID, &sampleTypeID, &status); err != nil {
		writeError(w, http.StatusNotFound, "sample_not_found", "sample not found")
		return
	}
	// verify user assigned to that laboratory (or admin)
	var assignedLab string
	_ = s.PG.QueryRow(r.Context(), `SELECT assigned_lab FROM app_user WHERE id=$1`, uid).Scan(&assignedLab)
	if role != models.RoleAdministrator && assignedLab != labID {
		writeError(w, http.StatusForbidden, "not_assigned_lab", "user not assigned to target laboratory")
		return
	}
	if _, err := s.PG.Exec(r.Context(), `UPDATE sample SET status='received', received_lab_id=$1, current_holder_id=$2, exception='' WHERE id=$3`, labID, uid, req.SampleID); err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if req.AssignmentID != "" {
		_, _ = s.PG.Exec(r.Context(), `UPDATE assignment SET status='completed', completed_at=$1 WHERE id=$2`, req.ReceivedAt, req.AssignmentID)
	}
	s.Audit.Record(r.Context(), uid, string(role), "confirm_laboratory_receipt", "sample", req.SampleID, true, req)
	s.Audit.TimelineEvent(r.Context(), req.SampleID, "", req.AssignmentID, uid, string(role), "laboratory_received", "sample", req.SampleID, true, req)
