package realtime

import (
	"context"
	"net/http"
	"sync"
	"time"

	"lablogistics/internal/events"

	"github.com/redis/go-redis/v9"
	nhoj "github.com/gorilla/websocket"
)

var upgrader = nhoj.Upgrader{
	CheckOrigin:     func(r *http.Request) bool { return true },
	ReadBufferSize:  1024,
	WriteBufferSize: 1024,
}

type Hub struct {
	broker *events.Broker
	rdb    *redis.Client
	mu     sync.Mutex
	cancels map[int64]context.CancelFunc
}

func NewHub(broker *events.Broker, rdb *redis.Client) *Hub {
	return &Hub{broker: broker, rdb: rdb, cancels: map[int64]context.CancelFunc{}}
}

func (h *Hub) HandleWS(w http.ResponseWriter, r *http.Request) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		return
	}
	id, ch := h.broker.Subscribe()
	ctx, cancel := context.WithCancel(context.Background())
	h.mu.Lock()
	h.cancels[id] = cancel
	h.mu.Unlock()

	go func() {
		defer func() {
			h.broker.Unsubscribe(id)
			cancel()
			_ = conn.Close()
		}()

		var external <-chan *redis.Message
		if h.rdb != nil {
			sub := h.rdb.Subscribe(ctx, events.Channel)
			external = sub.Channel()
			defer sub.Close()
		}

		closed := make(chan struct{})
		go func() {
			defer close(closed)
			for {
				if _, _, err := conn.NextReader(); err != nil {
					return
				}
			}
		}()

		ping := time.NewTicker(20 * time.Second)
		defer ping.Stop()

		for {
			select {
			case <-closed:
				return
			case ev, ok := <-ch:
				if !ok {
					return
				}
				_ = conn.WriteJSON(ev)
			case <-ping.C:
				_ = conn.WriteMessage(nhoj.PingMessage, nil)
			case msg, ok := <-external:
				if !ok {
					external = nil
					continue
				}
				_ = conn.WriteMessage(nhoj.TextMessage, []byte(msg.Payload))
			}
		}
	}()
}

